(function() {
    if (window.htmxoPreloadClient) return;
    var bytes = new Uint8Array(16), id = '';
    crypto.getRandomValues(bytes);
    for (var i = 0; i < bytes.length; i++) id += (bytes[i] < 16 ? '0' : '') + bytes[i].toString(16);
