  var chatThread, chatText, chatSendBtn, chatTitle, chatTodo, chatPick, chatClose, chatStatus;
  var chatOwner = '', chatTodoUrl = '', chatWs = null, chatPoll = null;
  var FUTURE_TS = '2099-01-01T00:00:00';
  var origPadBottom = null;

  // The bar is position:fixed;bottom:0, so it floats OVER the last bar-height
  // of page content. Reserve that space at the page bottom = the bar's CURRENT
  // height (collapsed ~30px / open / chat up to 60vh) so bottom content scrolls
  // clear above it. We add to the app's OWN body padding-bottom (captured once)
  // rather than clobbering it, and also expose the height as `--htmxo-overlay-h`
  // for apps that want it. A ResizeObserver on the bar keeps this in sync across
  // every state transition, async chat-content growth, and viewport resize.
  function syncOverlayPad() {
    if (!bar) { return; }
    if (origPadBottom === null) {
      origPadBottom = parseFloat(window.getComputedStyle(document.body).paddingBottom) || 0;
    }
    var h = bar.offsetHeight || 0;
    document.body.style.paddingBottom = (origPadBottom + h) + 'px';
    document.documentElement.style.setProperty('--htmxo-overlay-h', h + 'px');
  }

  function parseLocation() {
    var path = window.location.pathname || '/';
    var parts = path.split('/').filter(function(s) { return s.length > 0; });
    if (parts.length >= 2 && parts[0] === 'p') {
      ctx.proxied = true; ctx.app = parts[1]; ctx.route = '/' + parts.slice(2).join('/');
    } else {
      ctx.proxied = false; ctx.route = path;
    }
    if (ctx.route === '') { ctx.route = '/'; }
    ctx.url = window.location.href;
  }

  function buildBar() {
    bar = document.createElement('div');
    bar.id = 'htmxo-overlay-bar';
    bar.setAttribute('data-state', 'collapsed');
    bar.innerHTML =
      '<div class="hob-collapsed">' +
        '<span class="hob-secure" title="Secure deployment" hidden>&#128274;</span>' +
        '<span class="hob-id"><span class="hob-app"></span> · <span class="hob-route"></span></span>' +
        '<span class="hob-owner"></span>' +
        '<button type="button" class="hob-toggle">Report &#9650;</button>' +
      '</div>' +
      '<form class="hob-form">' +
        '<div class="hob-formhead"><span class="hob-secure" title="Secure deployment" hidden>&#128274;</span><span class="hob-fh-id"></span><span class="hob-fh-owner"></span>' +
          '<button type="button" class="hob-toggle">&#9660;</button></div>' +
        '<div class="hob-kind">' +
          '<label><input type="radio" name="hob-kind" value="bug" checked> bug</label>' +
          '<label><input type="radio" name="hob-kind" value="feedback"> feedback</label>' +
        '</div>' +
        '<textarea class="hob-text" rows="3" placeholder="what happened…"></textarea>' +
        '<div class="hob-opts">' +
          '<label><input type="checkbox" class="hob-incl-ctx" checked> route+state</label>' +
          '<label class="hob-errrow" hidden><input type="checkbox" class="hob-incl-err" checked> error-log <code class="hob-erruid"></code></label>' +
        '</div>' +
        '<div class="hob-actions"><span class="hob-status"></span>' +
          '<button type="button" class="hob-send">Send</button></div>' +
      '</form>' +
      '<div class="hob-chat">' +
        '<div class="hob-chathead">' +
          '<span class="hob-secure" title="Secure deployment" hidden>&#128274;</span>' +
          '<span class="hob-ch-title"></span>' +
          '<a class="hob-ch-todo" target="_blank" rel="noopener" hidden>todo &#8599;</a>' +
          '<button type="button" class="hob-ch-pick">change agent</button>' +
          '<button type="button" class="hob-ch-close">&#9660;</button>' +
        '</div>' +
        '<div class="hob-ch-thread"></div>' +
        '<div class="hob-ch-compose">' +
          '<textarea class="hob-ch-text" rows="2" placeholder="reply to this agent…"></textarea>' +
          '<button type="button" class="hob-ch-send">Send</button>' +
        '</div>' +
        '<div class="hob-ch-status"></div>' +
      '</div>';
    document.body.appendChild(bar);
    appEl = bar.querySelector('.hob-app');
    routeEl = bar.querySelector('.hob-route');
    collapsedOwner = bar.querySelector('.hob-owner');
    fhId = bar.querySelector('.hob-fh-id');
    fhOwner = bar.querySelector('.hob-fh-owner');
    errRow = bar.querySelector('.hob-errrow');
    errUid = bar.querySelector('.hob-erruid');
    statusEl = bar.querySelector('.hob-status');
    textEl = bar.querySelector('.hob-text');
    sendBtn = bar.querySelector('.hob-send');
    inclErr = bar.querySelector('.hob-incl-err');
    chatTitle = bar.querySelector('.hob-ch-title');
    chatTodo = bar.querySelector('.hob-ch-todo');
    chatPick = bar.querySelector('.hob-ch-pick');
    chatClose = bar.querySelector('.hob-ch-close');
    chatThread = bar.querySelector('.hob-ch-thread');
    chatText = bar.querySelector('.hob-ch-text');
    chatSendBtn = bar.querySelector('.hob-ch-send');
    chatStatus = bar.querySelector('.hob-ch-status');
    var toggles = bar.querySelectorAll('.hob-toggle');
    for (var i = 0; i < toggles.length; i++) { toggles[i].addEventListener('click', toggleOpen); }
    sendBtn.addEventListener('click', send);
    chatSendBtn.addEventListener('click', sendChat);
    chatPick.addEventListener('click', pickAgent);
    chatClose.addEventListener('click', closeChat);
    chatText.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendChat(); }
    });
  }

  function render() {
    var appLabel = ctx.app || '(app)';
    appEl.textContent = '🐞 ' + appLabel;
    routeEl.textContent = ctx.route;
    collapsedOwner.textContent = ctx.owner ? ('👤 ' + ctx.owner) : '';
    fhId.textContent = appLabel + ' · ' + ctx.route;
    fhOwner.textContent = ctx.owner ? ('owner: ' + ctx.owner) : '';
  }

  function refresh() { parseLocation(); render(); }

  function toggleOpen() {
    var open = bar.getAttribute('data-state') === 'open';
    bar.setAttribute('data-state', open ? 'collapsed' : 'open');
    if (!open) { statusEl.textContent = ''; refresh(); }
  }

  function resolveOwner() {
    var q = ctx.proxied ? ('slug=' + encodeURIComponent(ctx.app))
                        : ('port=' + encodeURIComponent(window.location.port));
    fetch('/agents/app_for_port?' + q, { headers: { 'Accept': 'application/json' } })
      .then(function(r) { return r.ok ? r.json() : null; })
      .then(function(d) {
        if (!d) { return; }
        if (d.slug && !ctx.app) { ctx.app = d.slug; }
        if (d.owner) { ctx.owner = d.owner; }
        render();
        // Direct access: the slug is only known once app_for_port resolves it.
        // (Proxied access already knows it from the path — see the init call.)
        if (!ctx.proxied) { applySecure(ctx.app); }
      })
      .catch(function() {});
  }

  // Surface the secure-deployment soft-guard (backend decision d22m82) in the
  // UI: /repos carries `secure` per slug, so when the resolved slug is secure
  // we reveal the 🔒 badges (collapsed strip + form/chat heads). Defensive and
  // async — any failure leaves the badges hidden (fail-safe: default not-secure).
  function applySecure(slug) {
    if (!slug) { return; }
    fetch('/repos', { headers: { 'Accept': 'application/json' } })
      .then(function(r) { return r.ok ? r.json() : null; })
      .then(function(list) {
        if (!list || !list.length) { return; }
        var secure = false;
        for (var i = 0; i < list.length; i++) {
          if (list[i] && list[i].name === slug) { secure = !!list[i].secure; break; }
        }
        if (!secure) { return; }
        var els = bar.querySelectorAll('.hob-secure');
        for (var j = 0; j < els.length; j++) { els[j].hidden = false; }
      })
      .catch(function() {});
  }

  function captureError(uid, status) {
    lastError = { uid: uid, status: status };
    errRow.hidden = false;
    errUid.textContent = uid ? ('#' + uid) : ('HTTP ' + status);
    var bug = bar.querySelector('input[name="hob-kind"][value="bug"]');
    if (bug) { bug.checked = true; }
  }

  function attachObservers() {
    document.body.addEventListener('htmx:pushedIntoHistory', refresh);
    document.body.addEventListener('htmx:historyRestore', refresh);
    window.addEventListener('popstate', refresh);
    document.body.addEventListener('htmx:afterSettle', refresh);
    document.body.addEventListener('htmx:afterRequest', function(e) {
      var xhr = e.detail && e.detail.xhr;
      if (!xhr) { return; }
      var failed = (e.detail.successful === false) || (xhr.status >= 400);
      if (!failed) { return; }
      var uid = '';
      try { uid = xhr.getResponseHeader('X-HTMXO-Error-Id') || ''; } catch (err) {}
      captureError(uid, xhr.status);
    });
    document.body.addEventListener('htmx:sendError', function(e) { captureError('', 0); });
  }

  function fetchThread(aroundTs) {
    var u = '/agents/' + encodeURIComponent(chatOwner) + '/messages?embedded=1&around=' + encodeURIComponent(aroundTs);
    // HX-Request: true => the KB returns the bare kb-msg-window fragment (no full-page
    // chrome); the kb-msg-window strip below is then just belt-and-suspenders.
    return fetch(u, { headers: { 'Accept': 'text/html', 'HX-Request': 'true' } })
      .then(function(r) { return r.ok ? r.text() : Promise.reject('HTTP ' + r.status); });
  }

  // Wake-safe anchor: seed_ts is a reliable LOWER BOUND, not the bubble's exact
  // ts (the woken-agent case stamps the turn ts async, a few seconds later). So
  // we highlight the newest from=user bubble with ts >= floorTs — the just-filed
  // report is always the newest user turn right after the POST — not an exact
  // data-ts == seed_ts match (which misses the wake case).
  function pickAnchor(floorTs) {
    var users = chatThread.querySelectorAll('.kb-bubble[data-role="user"]');
    var best = null;
    for (var i = 0; i < users.length; i++) {
      var ts = users[i].getAttribute('data-ts') || '';
      if (!floorTs || ts >= floorTs) { best = users[i]; }
    }
    if (best) { return best; }
    if (users.length) { return users[users.length - 1]; }
    var all = chatThread.querySelectorAll('.kb-bubble');
    return all.length ? all[all.length - 1] : null;
  }

  function injectThread(html, floorTs, keepScroll) {
    var atBottom = keepScroll && chatThread.scrollHeight > 0 &&
      (chatThread.scrollHeight - chatThread.scrollTop - chatThread.clientHeight) < 48;
    var tmp = document.createElement('div');
    tmp.innerHTML = html;
    // Defensive chrome-strip: keep only the message window until leg 3 slims embedded=1.
    var win = tmp.querySelector('.kb-msg-window');
    chatThread.innerHTML = '';
    chatThread.appendChild(win ? win : tmp);
    if (window.htmx) { try { window.htmx.process(chatThread); } catch (e) {} }
    if (keepScroll) {
      if (atBottom) { chatThread.scrollTop = chatThread.scrollHeight; }
      return;
    }
    var target = pickAnchor(floorTs);
    if (target) {
      target.classList.add('hob-anchor');
      target.scrollIntoView({ block: 'center' });
    } else {
      chatThread.scrollTop = chatThread.scrollHeight;
    }
  }

  function reloadLatest() {
    if (!chatOwner) { return; }
    fetchThread(FUTURE_TS).then(function(html) {
      injectThread(html, '', true);
    }).catch(function() {});
  }

  function subscribeWs() {
    if (chatWs) { try { chatWs.close(); } catch (e) {} chatWs = null; }
    try {
      var proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      var sock = new WebSocket(proto + '//' + window.location.host + '/agents/events');
      chatWs = sock;
      sock.onmessage = function(ev) {
        if ((ev.data || '') === ('messages:' + chatOwner)) { reloadLatest(); }
      };
      sock.onclose = function() { if (chatWs === sock) { chatWs = null; } };
      sock.onerror = function() {};
    } catch (e) { chatWs = null; }
  }

  function startPoll() {
    stopPoll();
    // Fallback until leg 3 wires the messages:<aid> live-push marker.
    chatPoll = setInterval(reloadLatest, 10000);
  }
  function stopPoll() { if (chatPoll) { clearInterval(chatPoll); chatPoll = null; } }

  function enterChat(owner, todoUrl, seedTs) {
    if (!owner) { return; }
    chatOwner = owner;
    chatTodoUrl = todoUrl || '';
    bar.setAttribute('data-state', 'chat');
    chatTitle.textContent = '💬 ' + owner;
    if (chatTodoUrl) { chatTodo.setAttribute('href', chatTodoUrl); chatTodo.hidden = false; }
    else { chatTodo.hidden = true; }
    chatStatus.textContent = 'loading…';
    var anchor = seedTs || FUTURE_TS;
    var highlight = seedTs || '';
    fetchThread(anchor).then(function(html) {
      injectThread(html, highlight, false);
      chatStatus.textContent = '';
    }).catch(function(err) {
      chatStatus.textContent = 'could not load thread (' + err + ')';
    });
    subscribeWs();
    startPoll();
  }

  function sendChat() {
    var msg = (chatText.value || '').trim();
    if (!msg || !chatOwner) { return; }
    chatSendBtn.disabled = true;
    chatStatus.textContent = 'sending…';
    var b = new URLSearchParams();
    b.set('from', 'user');
    b.set('message', msg);
    fetch('/agents/' + encodeURIComponent(chatOwner) + '/dispatch', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: b.toString()
    }).then(function(r) {
      if (!r.ok) { return Promise.reject('HTTP ' + r.status); }
    }).then(function() {
      chatText.value = '';
      chatStatus.textContent = '';
      reloadLatest();
    }).catch(function(err) {
      chatStatus.textContent = 'send failed (' + err + ')';
    }).then(function() { chatSendBtn.disabled = false; });
  }

  function pickAgent() {
    var who = window.prompt('Chat with which agent?', chatOwner);
    if (!who) { return; }
    who = who.trim();
    if (!who || who === chatOwner) { return; }
    enterChat(who, chatTodoUrl, '');
  }

  function closeChat() {
    if (chatWs) { try { chatWs.close(); } catch (e) {} chatWs = null; }
    stopPoll();
    bar.setAttribute('data-state', 'collapsed');
    statusEl.textContent = '';
    refresh();
  }

  function send() {
    refresh();
    var kindEl = bar.querySelector('input[name="hob-kind"]:checked');
    var inclErrOn = inclErr && !errRow.hidden && inclErr.checked;
    var body = new URLSearchParams();
    body.set('kind', kindEl ? kindEl.value : 'bug');
    body.set('text', textEl.value || '');
    body.set('app', ctx.app || '');
    body.set('route', ctx.route || '');
    body.set('url', ctx.url || '');
    var euid = (inclErrOn && lastError) ? (lastError.uid || '') : '';
    if (euid) { body.set('error_uid', euid); }
    // screenshot: reserved field, not captured in v1 (omitted when none).
    statusEl.textContent = 'sending…';
    sendBtn.disabled = true;
    fetch('/agents/report', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: body.toString()
    }).then(function(r) {
      if (!r.ok) { return Promise.reject('HTTP ' + r.status); }
      return r.json().catch(function() { return {}; });
    }).then(function(d) {
      textEl.value = '';
      var owner = (d && d.owner) ? d.owner : ctx.owner;
      var todoUrl = (d && d.todo_url) ? d.todo_url : '';
      // Seed ts from /report (ask #1, leg 1) — `seed_ts` is the contract key; it
      // is a LOWER BOUND used to scope the window (see pickAnchor). Empty => latest-window.
      var seedTs = (d && (d.seed_ts || d.ts || d.thread_ts)) || '';
      if (owner) {
        statusEl.textContent = 'filed → ' + owner;
        enterChat(owner, todoUrl, seedTs);
      } else {
        statusEl.textContent = 'filed';
        setTimeout(function() { bar.setAttribute('data-state', 'collapsed'); statusEl.textContent = ''; }, 1800);
      }
    }).catch(function(err) {
      statusEl.textContent = 'could not file (' + err + ')';
    }).then(function() { sendBtn.disabled = false; });
  }

  buildBar();
  parseLocation();
  render();
  resolveOwner();
  // Proxied access knows its slug from the /p/<slug>/ path right away — resolve
  // secure-ness immediately. (Direct access fires this from resolveOwner once
  // app_for_port supplies the slug.)
  if (ctx.proxied) { applySecure(ctx.app); }
  attachObservers();
  syncOverlayPad();
  // ResizeObserver catches every bar height change — state transitions
  // (collapsed↔open↔chat), async chat-thread growth, and 60vh shifts on
  // viewport resize — in one registration. The resize listener is a cheap
  // fallback for browsers without ResizeObserver.
  if (window.ResizeObserver) {
    try { new ResizeObserver(syncOverlayPad).observe(bar); } catch (e) {}
  }
  window.addEventListener('resize', syncOverlayPad);
});
"""))

"""
    KB_ORIGIN

Origin prefix for the relocated overlay bundle served at
`<KB_ORIGIN>/overlay/bar.js` — the thin-hook bootstrap `htmx(...; overlay=true)`
emits in place of the old inline `<style>`+`<script>`. Default `""` →
root-absolute `/overlay/bar.js`, same-origin under the supported `/p/<slug>/`
proxy. Set to an absolute origin (e.g. `"http://localhost:4200"`) for
direct-port / dev access; the pre-existing cross-origin runtime-fetch limit
then applies (the bar's own `/repos` + `/agents/...` calls are same-origin to
the *page*, not to `KB_ORIGIN`) — documented here, not solved.
"""
const KB_ORIGIN = ""

"""
    overlay_bar()

!!! note "Dead code as of the th8p6p thin-hook cutover"
    `htmx(...; overlay=true)` no longer injects this inline bundle — it emits a
    single `<script src=\$KB_ORIGIN/overlay/bar.js defer>` bootstrap instead, and
    the real `overlay_bar_script`/`overlay_bar_style` are served from the KB at
    `/overlay/bar.js`. These three definitions are retained (not called) only to
    keep the flip minimal + cleanly revertible; removal is a later follow-up.

Combined style + script for the framework debug/dev overlay bar (the v1
feedback spine). Was injected by [`htmx`](@ref) on full-page responses when
`overlay=true` (opt-in; the default is `false` outside the KB app). The bar resolves
its own context client-side and talks to the KB root-absolute, mirroring
[`request_feedback`](@ref)'s zero-server-context model.
"""
overlay_bar() = (overlay_bar_style(), overlay_bar_script())

"""
    compose_box_styles()

CSS for the [`compose_box`](@ref) auto-growing compose textarea. The toast it
raises on a failed submit is styled by [`toast_styles`](@ref). Deliberately
**unlayered** (not inside
`@layer htmxo`) so the `.htmxo-compose-textarea` class beats Pico's unlayered
`textarea { resize: … }` rule — a layered rule would lose regardless of
specificity and the drag-handle/scrollbar would reappear.
"""
compose_box_styles() = h.style(Raw(raw"""
.htmxo-compose-textarea {
    resize: none; overflow: hidden; field-sizing: content; line-height: 1.4;
}
"""))

"""
    compose_box_script()

JS driving [`compose_box`](@ref): auto-grow (no-op when the browser supports
`field-sizing: content`, JS fallback otherwise), the send key (Enter sends and
Shift+Enter inserts a new line; on a box with `data-htmxo-submit="modifier"`
Enter inserts a new line and Ctrl/Cmd+Enter sends, see `compose_box`'s
`submit`), localStorage draft persistence for `.htmxo-compose-draft`
elements (keyed by `data-draft-key`), and a submit guard on
`.htmxo-compose-form` forms (clear drafts + reset on success; on a failure,
network error or timeout, one toast saying the text is preserved, in place of
the shell's generic failure toast). It reads the outcome with
[`toast_script`](@ref)'s `window.htmxoRequestOutcome` and raises the toast
through `window.htmxoToast`, so it needs that runtime on the page.
Re-binds on `htmx:afterSwap` and
`htmx:afterSettle`; idempotent per element. The swap pass covers swaps
that never settle (one whose nodes an `afterSwap` listener detaches —
the `:auto` terminal unwrap — fires afterSwap but never afterSettle;
snag compose-afterswa-9ae50ac9). Exposes `window.htmxoComposeRebind(root)`
for reuse. Body-listener
attachment is deferred to `DOMContentLoaded` so the script is safe to
inject in `<head>`.
"""
compose_box_script() = h.script(Raw(raw"""
(function() {
    var FIELD_SIZING = !!(window.CSS && CSS.supports && CSS.supports('field-sizing', 'content'));
    function autoGrow(el) {
        if (!el || FIELD_SIZING) return;
        el.style.height = 'auto';
        el.style.height = el.scrollHeight + 'px';
    }
    function draftKey(el) { return el.getAttribute('data-draft-key') || ''; }
    function restoreDrafts(root) {
        var scope = root && root.querySelectorAll ? root : document;
        scope.querySelectorAll('.htmxo-compose-draft').forEach(function(el) {
            if (el.dataset.htmxoDraftBound === '1') return;
            el.dataset.htmxoDraftBound = '1';
            var k = draftKey(el);
            if (!k) return;
            try { var saved = localStorage.getItem(k); if (saved && !el.value) el.value = saved; } catch (e) {}
            if (el.classList.contains('htmxo-compose-textarea')) autoGrow(el);
            el.addEventListener('input', function() {
                try { if (el.value) localStorage.setItem(k, el.value); else localStorage.removeItem(k); } catch (e) {}
            });
        });
    }
    function bindTextareas(root) {
        var scope = root && root.querySelectorAll ? root : document;
        scope.querySelectorAll('.htmxo-compose-textarea').forEach(function(el) {
            if (el.dataset.htmxoTaBound === '1') { autoGrow(el); return; }
            el.dataset.htmxoTaBound = '1';
            autoGrow(el);
            el.addEventListener('input', function() { autoGrow(el); });
            el.addEventListener('keydown', function(e) {
                if (e.key !== 'Enter') return;
                // data-htmxo-submit="modifier": Enter and Shift+Enter keep
                // their new line and Ctrl/Cmd+Enter sends. Otherwise Enter
                // sends and Shift+Enter keeps its new line. Read on every
                // press, so a box re-rendered in another mode needs no rebind.
                var send = el.getAttribute('data-htmxo-submit') === 'modifier'
                    ? (e.ctrlKey || e.metaKey)
                    : !e.shiftKey;
                if (!send) return;
                e.preventDefault();
                var f = el.closest('form');
                if (!f) return;
                if (f.requestSubmit) f.requestSubmit();
                else f.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
            });
        });
    }
    function clearFormDrafts(form) {
        form.querySelectorAll('.htmxo-compose-draft').forEach(function(el) {
            var k = draftKey(el); if (!k) return;
            try { localStorage.removeItem(k); } catch (e) {}
        });
    }
    function toast(text, status) { window.htmxoToast(text, status); }
    window.htmxoComposeRebind = function(root) { restoreDrafts(root); bindTextareas(root); };
    function init() {
        restoreDrafts(document);
        bindTextareas(document);
        // Bind on swap as well as settle: a swap whose nodes an `afterSwap`
        // listener detaches (the `:auto` terminal unwrap) fires afterSwap but
        // never afterSettle, and boxes arriving with it would stay dead
        // (snag compose-afterswa-9ae50ac9). The rebind is idempotent per
        // element (dataset flags), so the settle pass is a no-op for boxes
        // the swap pass already bound.
        document.body.addEventListener('htmx:afterSwap', function(evt) {
            restoreDrafts(evt.detail && evt.detail.elt);
            bindTextareas(evt.detail && evt.detail.elt);
        });
        document.body.addEventListener('htmx:afterSettle', function(evt) {
            restoreDrafts(evt.detail && evt.detail.elt);
            bindTextareas(evt.detail && evt.detail.elt);
        });
        // Success → clear drafts + reset the form. A failure → keep the text
        // and say so, in place of the shell's generic failure toast (this
        // listener runs first and claims the request's one failure message).
        function finished(evt) {
            var form = evt.target && evt.target.closest && evt.target.closest('.htmxo-compose-form');
            if (!form || !evt.detail) return;
            var result = window.htmxoRequestOutcome(evt);
            if (result.state === 'success') {
                clearFormDrafts(form);
                form.reset();
                form.querySelectorAll('.htmxo-compose-textarea').forEach(autoGrow);
            } else if (result.state === 'failure' && !evt.detail.htmxoFailureShown) {
                evt.detail.htmxoFailureShown = true;
                toast(evt.type === 'htmx:sendError'
                    ? 'send failed — unreachable; your text is preserved'
                    : 'send failed — your text is preserved, retry when ready', 'error');
            }
        }
        ['htmx:afterRequest', 'htmx:sendError', 'htmx:timeout'].forEach(function(name) {
            document.body.addEventListener(name, finished);
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
    else init();
})();
"""))

"""
    compose_box_assets()

Combined style + script nodes for [`compose_box`](@ref). Injected into the
page head by `htmx(...)` when `compose=true` (the default), mirroring
[`request_feedback`](@ref).
"""
compose_box_assets() = (toast_styles(), toast_script(), compose_box_styles(), compose_box_script())

# --- Toasts ---

"""
    toast_styles()

CSS for the [`toast_script`](@ref) notifications: a fixed stack in the
bottom-right corner (no layout shift), each toast a card with a status edge
from `--htmxo-success` / `--htmxo-accent` / `--htmxo-error` and a dismiss
button. Light and dark follow Pico's card colours, else the system
`Canvas`/`CanvasText` of the page's colour scheme. Unlayered, so the dismiss
button beats Pico's unlayered `button` rule. [`htmx`](@ref) includes it.
"""
toast_styles() = h.style(Raw(raw"""
.htmxo-toasts {
    position: fixed; inset-block-end: 1rem; inset-inline-end: 1rem; z-index: 9999;
    display: flex; flex-direction: column; align-items: flex-end; gap: .5rem;
    max-width: min(28rem, calc(100vw - 2rem)); pointer-events: none;
}
.htmxo-toast {
    pointer-events: auto; display: flex; align-items: flex-start; gap: .5rem;
    padding: .5rem .4rem .5rem .85rem; border-radius: .3rem; font-size: .9em; line-height: 1.4;
    background: var(--pico-card-background-color, Canvas); color: var(--pico-color, CanvasText);
    border: 1px solid var(--pico-muted-border-color, color-mix(in srgb, currentColor 25%, transparent));
    border-inline-start: .25rem solid var(--htmxo-accent, Highlight);
    box-shadow: 0 2px 8px rgba(0, 0, 0, .2);
    opacity: 0; transform: translateY(.5rem); transition: opacity .25s ease, transform .25s ease;
}
.htmxo-toast-show { opacity: 1; transform: none; }
.htmxo-toast-success { border-inline-start-color: var(--htmxo-success, #2a9d8f); }
.htmxo-toast-error { border-inline-start-color: var(--htmxo-error, #e76f51); }
.htmxo-toast > span { flex: 1; overflow-wrap: anywhere; }
.htmxo-toast > .htmxo-toast-close {
    width: auto; margin: 0; padding: 0 .3rem; border: none; border-radius: .2rem;
    background: transparent; color: inherit; font: inherit; line-height: 1.4;
    box-shadow: none; cursor: pointer; opacity: .7;
}
.htmxo-toast > .htmxo-toast-close:hover, .htmxo-toast > .htmxo-toast-close:focus-visible { opacity: 1; }
.htmxo-toast > .htmxo-toast-close:focus-visible { outline: 2px solid var(--htmxo-accent, Highlight); outline-offset: 1px; }
@media (prefers-reduced-motion: reduce) { .htmxo-toast { transition: none; transform: none; } }
"""))

"""
    toast_script()

The page shell's notification runtime, which [`htmx`](@ref) includes:

- `window.htmxoToast(text, status)` shows a toast (`status` `"success"`,
  `"info"` (default) or `"error"`). Toasts stack in one polite live region
  (`role="status"`); an error toast is also `role="alert"`. Each has a
  Dismiss button and leaves after 4 s (8 s for an error), paused while
  hovered or focused.
- **A route names its success toast** with the `X-HTMXO-Toast` response header
  (percent-encoded text; [`hx_response`](@ref)`(value; toast="Saved")` sets
  it). It is shown once, after a successful request: a polled `:auto` mutation
  carries it on its terminal response only. A failed request shows no success
  toast; its error presentation is unchanged.
- **An element can toast its own response.** On a requesting element (or an
  ancestor), `data-htmxo-toast="body"` (or an empty value) toasts the
  response's text on success, and any other value is the success text itself.
  This suits `hx-swap="none"` actions whose response is their outcome
  message. A route's header text wins.
- **A failed request raises one error toast**, whatever element sent it: an
  answer htmx does not swap because of its status (a gateway's 413 or 502, a
  router's 404, a short `text/plain` refusal), no answer at all, or a timeout.
  The text names the status and its reason, read from the answer's `<title>`
  when `statusText` is empty (HTTP/2), plus a short `text/plain` body or an
  HTML title/heading that says more: "Request failed (HTTP 413 Request Entity
  Too Large)", "Request failed (HTTP 409 Conflict): already stopped",
  "Request failed: no response (network error or server unreachable)",
  "Request timed out" — in the page's `htmx(...; error_texts)`, so
  `error_texts(:de)` writes "Anfrage fehlgeschlagen (HTTP 502 Fehlerhaftes
  Gateway)". HTMXObjects' own error articles are 2xx answers that
  land in the target, so they raise none. A request the page aborted, an
  answer that navigates (`HX-Redirect`, `HX-Refresh`, `HX-Location`), an error
  answer an app's `htmx.config.responseHandling` swaps in, and pollers
  (`hx-trigger="every …"`) and preloads raise none either. An identical error
  toast already on screen counts the repeat ("(×3)") instead of stacking.
  A listener that shows its own failure message sets
  `evt.detail.htmxoFailureShown = true` while the request's events dispatch,
  an element's `hx-on::after-request` included, since the toast waits for
  them (as [`compose_box_script`](@ref) does, and the lazy master/detail
  loader for an attempt it retries by itself).
- `window.htmxoRequestOutcome(evt)` classifies an `htmx:afterRequest`,
  `htmx:sendError`, `htmx:timeout` or `htmx:sendAbort` event as
  `{state: "success" | "failure" | "neutral" | "pending", text}`, the reading
  [`request_feedback_script`](@ref) and the compose box share.
"""
toast_script() = h.script(Raw(raw"""
(function() {
    if (window.__htmxoToastBound) return;
    window.__htmxoToastBound = true;
    var DURATION = { success: 4000, info: 4000, error: 8000 };
    // The page's error texts (`htmx(...; error_texts)` puts them on <html>),
    // or English.
    var ENGLISH = """ * _toast_texts_json(_EN_ERROR_TEXTS) * raw""";
    var textsRaw = null, textsRead = ENGLISH;
    function texts() {
        var raw = document.documentElement.getAttribute('data-htmxo-error-texts');
        if (raw !== textsRaw) { textsRaw = raw; textsRead = raw ? JSON.parse(raw) : ENGLISH; }
        return textsRead;
    }
    // The live region exists before the first message, so screen readers
    // announce it; a swap that replaced the body gets a fresh one.
    function region() {
        var r = document.getElementById('htmxo-toasts');
        if (!r && document.body) {
            r = document.createElement('div');
            r.id = 'htmxo-toasts';
            r.className = 'htmxo-toasts';
            r.setAttribute('role', 'status');
            r.setAttribute('aria-live', 'polite');
            document.body.appendChild(r);
        }
        return r;
    }
    // An error toast whose text is already on screen counts the repeat instead
    // of stacking a copy: a gateway outage fails every request on the page.
    var shownErrors = {};
    function toast(text, status) {
        status = status || 'info';
        var same = status === 'error' && shownErrors[text];
        if (same) { same.repeat(); return same.node; }
        var t = document.createElement('div');
        t.className = 'htmxo-toast htmxo-toast-' + status;
        if (status === 'error') t.setAttribute('role', 'alert');
        var msg = document.createElement('span');
        msg.textContent = text;
        var close = document.createElement('button');
        close.type = 'button';
        close.className = 'htmxo-toast-close';
        close.setAttribute('aria-label', texts().dismiss);
        close.textContent = '×';
        t.appendChild(msg);
        t.appendChild(close);
        var timer = null, held = false, count = 1;
        function dismiss() {
            clearTimeout(timer);
            if (shownErrors[text] && shownErrors[text].node === t) delete shownErrors[text];
            t.classList.remove('htmxo-toast-show');
            setTimeout(function() { t.remove(); }, 300);
        }
        function arm() { clearTimeout(timer); if (!held) timer = setTimeout(dismiss, DURATION[status] || 4000); }
        function hold() { held = true; clearTimeout(timer); }
        function release() { held = false; arm(); }
        close.addEventListener('click', dismiss);
        t.addEventListener('mouseenter', hold);
        t.addEventListener('mouseleave', release);
        t.addEventListener('focusin', hold);
        t.addEventListener('focusout', release);
        if (status === 'error') shownErrors[text] = { node: t, repeat: function() {
            count += 1;
            msg.textContent = text + ' (×' + count + ')';
            arm();
        } };
        region().appendChild(t);
        void t.offsetWidth;
        t.classList.add('htmxo-toast-show');
        arm();
        return t;
    }
    window.htmxoToast = toast;

    function header(xhr, name) {
        try { return xhr.getResponseHeader(name); } catch (e) { return null; }
    }
    function routeText(xhr) {
        var raw = header(xhr, 'X-HTMXO-Toast');
        if (!raw) return null;
        try { return decodeURIComponent(raw); } catch (e) { return raw; }
    }
    function bodyText(xhr) {
        var body = xhr.responseText || '';
        if ((header(xhr, 'Content-Type') || '').indexOf('text/plain') >= 0) return body.trim();
        var doc = new DOMParser().parseFromString(body, 'text/html');
        return (doc.body.textContent || '').replace(/\s+/g, ' ').trim();
    }
    function squash(text) { return (text || '').replace(/\s+/g, ' ').trim(); }
    // Over HTTP/2 `statusText` is empty, so the reason comes from the answer's
    // own `<title>` (a gateway's "413 Request Entity Too Large") or the texts'
    // table; a page in another language names the status from its table first,
    // since `statusText` and gateway titles are English.
    function failureText(xhr) {
        var type = header(xhr, 'Content-Type') || '', body = xhr.responseText || '';
        var plain = '', title = '', heading = '';
        if (type.indexOf('text/plain') >= 0) plain = body.trim();
        else if (type.indexOf('html') >= 0 && body.length <= 100000) {
            var doc = new DOMParser().parseFromString(body, 'text/html');
            var h = doc.querySelector('h1, h2');
            title = squash(doc.title);
            heading = h ? squash(h.textContent) : '';
        }
        var t = texts();
        var reason = (t !== ENGLISH && t.reasons[xhr.status]) || squash(xhr.statusText);
        var named = title.match(/^(\d{3})\s+(.+)$/);
        if (!reason && named && +named[1] === xhr.status) reason = named[2];
        if (!reason) reason = t.reasons[xhr.status] || '';
        var line = 'HTTP ' + xhr.status + (reason ? ' ' + reason : '');
        // A title or heading that names this status code, in any wording, is
        // the status line again, not a detail.
        function restates(text) {
            var named = text.match(/^(?:HTTP\s+)?(\d{3})(\s|:|$)/i);
            return (named && +named[1] === xhr.status) || text.toLowerCase() === reason.toLowerCase();
        }
        var detail = plain && plain.length <= 300 ? plain :
            [title, heading].filter(function(text) { return text && text.length <= 200 && !restates(text); })[0];
        return t.request_failed + ' (' + line + ')' + (detail ? ': ' + detail : '');
    }
    // How a finished htmx request ended: `success`; `failure`, with the text
    // that says why; `neutral`, for a request the page aborted or an answer
    // that navigates (HX-Redirect, HX-Refresh, HX-Location); or `pending` for
    // an `htmx:afterRequest` without a status, which htmx follows at once with
    // the `htmx:sendError` / `htmx:timeout` / `htmx:sendAbort` that decides it.
    // `shown` marks an error answer htmx swapped in anyway (an app's own
    // `responseHandling`): it is on screen already.
    function outcome(evt) {
        var d = evt.detail || {}, xhr = d.xhr;
        if (evt.type === 'htmx:sendError') return { state: 'failure', text: texts().no_response };
        if (evt.type === 'htmx:timeout') return { state: 'failure', text: texts().timed_out };
        if (evt.type === 'htmx:sendAbort') return { state: 'neutral' };
        if (!xhr || !xhr.status) return { state: 'pending' };
        if (d.successful === true) return { state: 'success' };
        if (d.failed === true) return { state: 'failure', text: failureText(xhr), shown: xhr.__htmxoErrorSwapped === true };
        return { state: 'neutral' };
    }
    window.htmxoRequestOutcome = outcome;
    document.addEventListener('htmx:beforeSwap', function(evt) {
        var d = evt.detail || {};
        if (d.isError && d.xhr) d.xhr.__htmxoErrorSwapped = !!d.shouldSwap;
    });
    // Pollers and preloads are background work: they fail silently, as they
    // pulse silently.
    function background(d, elt) {
        var headers = d.requestConfig && d.requestConfig.headers;
        var trigger = elt && elt.getAttribute ? elt.getAttribute('hx-trigger') || '' : '';
        return trigger.indexOf('every') !== -1 || !!(headers && headers['HX-Preloaded'] === 'true');
    }
    function finished(evt) {
        var d = evt.detail || {}, xhr = d.xhr;
        if (!xhr) return;
        var elt = (d.requestConfig && d.requestConfig.elt) || d.elt;
        var result = outcome(evt);
        if (result.state === 'success') {
            var own = elt && elt.closest ? elt.closest('[data-htmxo-toast]') : null;
            var text = routeText(xhr);
            if (text === null && own) {
                var given = own.getAttribute('data-htmxo-toast');
                text = given && given !== 'body' ? given : bodyText(xhr);
            }
            if (text) toast(text, 'success');
        } else if (result.state === 'failure' && !result.shown && !background(d, elt) && !d.__htmxoFailureQueued) {
            // One failure message per request. A listener that shows its own
            // sets `htmxoFailureShown`; waiting for the microtask lets every
            // listener of this request's events run first, including an
            // element's `hx-on::after-request`, which htmx dispatches (as the
            // kebab-case alias) only after this document listener.
            d.__htmxoFailureQueued = true;
            queueMicrotask(function() {
                if (d.htmxoFailureShown) return;
                d.htmxoFailureShown = true;
                toast(result.text, 'error');
            });
        }
    }
    ['htmx:afterRequest', 'htmx:sendError', 'htmx:timeout'].forEach(function(name) {
        document.addEventListener(name, finished);
    });
    if (document.body) region();
    else document.addEventListener('DOMContentLoaded', region);
})();
"""))

"""
    compose_box(name; value="", placeholder="", draft_key=nothing, rows=1, class="", submit=:enter)

Emit an auto-growing `<textarea>` compose box: it sizes to its content (one row
when empty via `rows=1`, growing with each wrapped/entered line, no scrollbar
or drag handle), and submits its enclosing `<form>` from the keyboard.

`submit` chooses the key that sends:

- `:enter` (the default): Enter sends, Shift+Enter inserts a new line.
- `:modifier`: Enter and Shift+Enter insert a new line; Ctrl+Enter or
  Cmd+Enter sends. The form's own submit button sends either way. Use it where
  readers write several lines or do not expect Enter to send. The box carries
  `data-htmxo-submit="modifier"`; a hand-written `htmxo-compose-textarea`
  opts in with the same attribute.

Any other value throws an `ArgumentError`.

For the draft-persistence and submit-feedback behaviour, the surrounding form
should carry the `htmxo-compose-form` class — then a 2xx submit clears drafts +
resets the box and a failed/again-unreachable submit raises a toast while
preserving the typed text. Pass `draft_key` to persist the in-progress text to
`localStorage` under that key (the box also gets the `htmxo-compose-draft`
class). All behaviour is driven by [`compose_box_assets`](@ref), injected by
`htmx(...; compose=true)` by default.
"""
function compose_box(name; value="", placeholder="", draft_key=nothing, rows=1, class="",
                     submit=:enter)
    submit in (:enter, :modifier) || throw(ArgumentError(
        "compose_box: submit must be :enter or :modifier, got $(repr(submit))"))
    cls = "htmxo-compose-textarea"
    isnothing(draft_key) || (cls *= " htmxo-compose-draft")
    isempty(class)       || (cls *= " " * class)
    attrs = (; name, rows, placeholder, class=cls)
    isnothing(draft_key) || (attrs = (; attrs..., data_draft_key=draft_key))
    # `:enter` is the script's default, so it adds nothing to the markup.
    submit === :modifier && (attrs = (; attrs..., data_htmxo_submit="modifier"))
    h.textarea(value; attrs...)
end

include("live_thread.jl")

"""
    loading_indicator_script()

Return a `Node` `<script>` that sets `aria-busy` on HTMX target elements during
requests. Pico CSS renders a spinner automatically for `aria-busy` elements.

!!! note
    Deprecated in favor of `request_feedback()` which provides richer visual feedback.
"""
loading_indicator_script() = h.script(Raw("""
document.body.addEventListener('htmx:beforeRequest', function(e) {
    var config = e.detail.requestConfig;
    if (config && config.headers && config.headers['HX-Preloaded'] === 'true') return;
    e.detail.elt.setAttribute('aria-busy', 'true');
});
document.body.addEventListener('htmx:afterRequest', function(e) {
    e.detail.elt.removeAttribute('aria-busy');
});
"""))

# --- Tabset ---

"""
    tabset_styles()

CSS that draws `tabset(...)`'s `<nav>` + `.tab-panel` markup as an underline
tab bar: a thin rule under the tabs, the other tabs in the muted text color
(`--htmxo-muted`), and the open tab in the text color with an accent
underline (`--htmxo-accent`) over the rule. The panel below is unframed.
The rule's color is `--htmxo-tab-rule`, by default the text color at 20%;
set it on `.tabset` (or `:root`) to change it.

Scoped to `.tabset` on the outer `<div>`, so plain `<nav><ul>` menus elsewhere
are untouched, and complete without Pico. Intentionally unlayered: Pico
spaces `nav li` and `nav a` unlayered, and an unlayered declaration beats
every `@layer htmxo` one regardless of specificity, so layered rules left the
open tab floating above its rule. Auto-included by `htmx()`; inject manually
via `extra_head` if you're building your own `<head>`.
"""
tabset_styles() = h.style(Raw("""
.tabset > nav {
    display: block;
    margin: 0;
    padding: 0;
    box-shadow: inset 0 -1px 0 var(--htmxo-tab-rule, color-mix(in srgb, currentColor 20%, transparent));
}
.tabset > nav > ul {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 0;
    margin: 0;
    padding: 0;
    list-style: none;
}
.tabset > nav > ul > li {
    display: block;
    margin: 0;
    padding: 0;
}
.tabset > nav > ul > li > a {
    display: block;
    margin: 0;
    padding: 0.6rem 1rem;
    border: none;
    border-bottom: 2px solid transparent;
    border-radius: 0.25rem 0.25rem 0 0;
    background: transparent;
    color: var(--htmxo-muted);
    text-decoration: none;
    transition: color 0.15s ease-in-out, border-color 0.15s ease-in-out, background-color 0.15s ease-in-out;
}
.tabset > nav > ul > li > a:hover {
    color: inherit;
    border-bottom-color: color-mix(in srgb, currentColor 35%, transparent);
    background: color-mix(in srgb, currentColor 6%, transparent);
}
.tabset > nav > ul > li > a.contrast {
    color: inherit;
    border-bottom-color: var(--htmxo-accent);
    background: transparent;
}
.tabset > .tab-panel {
    padding: 1rem 0 0;
}
"""))

"""
    tabset_script()

JS that keeps a [`tabset`](@ref)'s open tab in the page URL. A tab click
replaces the tabset's URL parameter with the tab's name, and a page opened
with that parameter — reloaded, reached with Back, or a shared link — shows the
named tab. Auto-included by `htmx()`; inject manually via `extra_head` (next to
[`tabset_styles`](@ref)) if you're building your own `<head>`.
"""
tabset_script() = h.script(Raw("""
(() => {
    if (window.htmxoTabset) return;
    const links = ts => Array.from(ts.querySelectorAll(':scope > nav a[data-tab-name]'));
    const panelOf = (ts, a) => ts.querySelector(':scope > .tab-panel[data-panel="' + a.dataset.panel + '"]');
    const recording = ts => Boolean(ts.dataset.tabParam) && !ts.closest('.htmxo-embed');

    // Shows tab `a` before htmx has processed the tabset. A lazy panel that is
    // shown loads itself once visible, a hidden one from its tab's first click
    // (`_tabset_panel` / `_tabset_lazy_link_attrs`), so those attributes move
    // with the tab and htmx arms the right ones: the default tab's lazy panel
    // is never fetched for a tab the URL hides.
    const open = (ts, a) => {
        const from = links(ts).find(l => l.classList.contains('contrast'));
        const shown = from && panelOf(ts, from), target = panelOf(ts, a);
        if (shown && shown.hasAttribute('hx-get')) {
            from.setAttribute('hx-get', shown.getAttribute('hx-get'));
            from.setAttribute('hx-target', '#' + shown.id);
            from.setAttribute('hx-swap', 'innerHTML');
            from.setAttribute('hx-trigger', 'click once');
            if (ts.dataset.tabPreload) from.setAttribute('preload', ts.dataset.tabPreload);
            ['hx-get', 'hx-trigger', 'hx-swap'].forEach(n => shown.removeAttribute(n));
        }
        if (a.hasAttribute('hx-get')) {
            target.setAttribute('hx-get', a.getAttribute('hx-get'));
            target.setAttribute('hx-trigger', 'intersect once');
            target.setAttribute('hx-swap', 'innerHTML');
            ['hx-get', 'hx-target', 'hx-swap', 'hx-trigger', 'preload'].forEach(n => a.removeAttribute(n));
        }
        links(ts).forEach(l => { l.classList.remove('contrast'); l.classList.add('secondary'); });
        a.classList.remove('secondary');
        a.classList.add('contrast');
        ts.querySelectorAll(':scope > .tab-panel').forEach(p => p.classList.add('u-hidden'));
        target.classList.remove('u-hidden');
    };

    // Called by the script each tabset renders as its last child, so it runs
    // while the tabset is inserted: during parsing, or on an htmx swap before
    // htmx's settle-time processing. The URL's tab shows from the start.
    const warned = new Set();
    window.htmxoTabset = ts => {
        if (!recording(ts)) return;
        const key = ts.dataset.tabParam;
        const name = new URLSearchParams(location.search).get(key);
        if (name === null) return;
        const a = links(ts).find(l => l.dataset.tabName === name);
        if (a) { if (!a.classList.contains('contrast')) open(ts, a); return; }
        // Tabsets that share a parameter share its value: warn only when no
        // tabset on the page has a tab of that name.
        setTimeout(() => {
            const known = Array.from(document.querySelectorAll('.tabset > nav a[data-tab-name]')).some(l =>
                l.dataset.tabName === name && l.closest('.tabset').dataset.tabParam === key);
            if (known || warned.has(key + '=' + name)) return;
            warned.add(key + '=' + name);
            console.warn('tabset: no tab is named "' + name + '" (?' + key + '=); showing the default tab');
        }, 0);
    };

    // A tab click records its name. Capture phase, because the tab's hyperscript
    // halts the click. The history entry is replaced, not pushed, and keeps its
    // state: htmx 2 restores an entry on Back/Forward only when that state says
    // `htmx`. htmx files its Back snapshot of this page under the path it keeps
    // in sessionStorage (`saveCurrentPageToHistory`), so that path follows the
    // address too; where storage is blocked htmx keeps the path in memory and
    // refetches the page on Back instead, which shows the same tab.
    document.addEventListener('click', e => {
        const a = e.target instanceof Element ? e.target.closest('.tabset > nav a[data-tab-name]') : null;
        if (!a) return;
        const ts = a.closest('.tabset');
        if (!recording(ts)) return;
        const url = new URL(location.href);
        url.searchParams.set(ts.dataset.tabParam, a.dataset.tabName);
        if (url.href === location.href) return;
        history.replaceState(history.state, '', url);
        if (window.htmx) try { sessionStorage.setItem('htmx-current-path-for-history', url.pathname + url.search); } catch (_) {}
    }, true);
})();
"""))

_tabset_panel_id(id, i) = "$id-tab-$i"

# String content = URL → lazy. The initially active panel loads itself once it
# is actually visible; every other panel is filled by its tab's first click
# (see `_tabset_lazy_link_attrs`). Deliberately not `revealed`: htmx 2 measures
# a `display:none` panel as a zero-size box at the viewport origin, "reveals" it
# at once, and every hidden tab would load with the page.
function _tabset_panel(content::AbstractString, i, active, id)
    h.div(;
        id=_tabset_panel_id(id, i),
        class=i == active ? "tab-panel u-w-full" : "tab-panel u-w-full u-hidden",
        data_panel="tab-$i",
        (i == active ?
            (hx_get=content, hx_trigger="intersect once", hx_swap="innerHTML") :
            (;))...,
    )
end
function _tabset_panel(content, i, active, id)
    # Non-string content = eager render
    h.div(content;
        id=_tabset_panel_id(id, i),
        class=i == active ? "tab-panel u-w-full" : "tab-panel u-w-full u-hidden",
        data_panel="tab-$i",
    )
end

# A lazy tab that starts hidden fetches its panel from the tab link itself, on
# the first click only — which is also what lets `preload` warm it on hover.
# `tabset_script` moves these attributes and the panel's when a page opened
# with the tab in its URL shows another tab than `active`; keep the two alike.
_tabset_lazy_link_attrs(content::AbstractString, i, active, id, preload) =
    i == active ? (;) : (;
        hx_get=content,
        hx_target="#" * _tabset_panel_id(id, i),
        hx_swap="innerHTML",
        hx_trigger="click once",
        _preload_attrs(preload)...,
    )
_tabset_lazy_link_attrs(content, i, active, id, preload) = (;)

# A tab's name in the URL unless `names` gives one: its label lowercased, with
# ä ö ü ß spelled ae oe ue ss, other accents dropped, and every other run of
# characters one `-` ("Güte der Messungen (K-40)" → "guete-der-messungen-k-40").
# A label that is not text, or keeps no letter or digit, is named by position.
function _tabset_slug(label::AbstractString, i)
    s = replace(lowercase(label), "ä" => "ae", "ö" => "oe", "ü" => "ue", "ß" => "ss")
    s = strip(replace(Base.Unicode.normalize(s; stripmark=true), r"[^a-z0-9]+" => "-"), '-')
    isempty(s) ? string(i) : String(s)
end
_tabset_slug(label, i) = string(i)

_tabset_names(tabs, ::Nothing) = [_tabset_slug(label, i) for (i, (label, _)) in enumerate(tabs)]
function _tabset_names(tabs, names)
    length(names) == length(tabs) || throw(ArgumentError(
        "tabset: `names` has $(length(names)) entries for $(length(tabs)) tabs"))
    String[string(name) for name in names]
end

# One name per tab, each its own: the URL and `active` pick a tab by it.
function _tabset_checked_names(names)
    for (i, name) in enumerate(names)
        isempty(name) && throw(ArgumentError("tabset: tab $i has an empty name; give it one with `names=`"))
        j = findfirst(==(name), names)
        j == i || throw(ArgumentError(
            "tabset: tabs $j and $i are both named \"$name\"; tell them apart with `names=`"))
    end
    names
end

_tabset_active_index(active::Integer, names) = active
function _tabset_active_index(active::AbstractString, names)
    i = findfirst(==(active), names)
    isnothing(i) && throw(ArgumentError(
        "tabset: no tab is named \"$active\"; the names are $(join(repr.(names), ", "))"))
    i
end

# What lets `tabset_script` keep the open tab in the URL: the key on the
# tabset (with the `preload` trigger a lazy tab regains when the URL opens
# another one), each tab's name, and the call that shows the URL's tab.
_tabset_url_attrs(::Nothing, preload) = (;)
function _tabset_url_attrs(url_param::AbstractString, preload)
    isempty(url_param) && throw(ArgumentError("tabset: `url_param` is empty; pass `nothing` to keep the tab out of the URL"))
    trigger = _preload_attrs(preload)
    (; data_tab_param=url_param, (isempty(trigger) ? (;) : (; data_tab_preload=trigger.preload))...)
end
_tabset_name_attrs(::Nothing, names, i) = (;)
_tabset_name_attrs(url_param, names, i) = (; data_tab_name=names[i])

# Runs while the tabset is inserted — during parsing, or on an htmx swap
# before htmx and hyperscript process it (`tabset_script`).
const _TABSET_URL_RESTORE = "(window.htmxoTabset || (ts => ts.closest('.htmxo-embed') || " *
    "console.warn('tabset: tabset_script() is not on this page, so the open tab is not kept in the URL')))" *
    "(document.currentScript.parentElement)"
_tabset_url_restore(::Nothing) = ()
_tabset_url_restore(url_param) = (h.script(Raw(_TABSET_URL_RESTORE)),)

# The tab bar or one panel of a `tabset`, in every format. HTML and HXML write
# the node as the browser shows it. Markdown, which a `?plain` reader or a PDF
# reads top to bottom with no tab to click, writes `markdown` instead: nothing
# for the tab bar, and each tab as its label in bold followed by its content —
# what `SemanticDisclosure` writes for a label and the body it opens, so a tab
# whose content its reader does not see goes with its label. A lazy tab's
# content is not on the page, so its label links the address that has it. The
# walkers that read the HTML (`?error`, static export, prestart, layout checks)
# see through to the node.
struct _TabsetPart
    node::Node
    markdown::Any
end
Base.show(io::IO, m::MIME"text/html", p::_TabsetPart) = show(io, m, p.node)
Base.show(io::IO, m::MIME"application/vnd.hyperview+xml", p::_TabsetPart) = show(io, m, p.node)
function Base.show(io::IO, m::MIME"text/markdown", p::_TabsetPart)
    _shows_nothing(p.markdown, _ambient_audience()) || show(io, m, p.markdown)
    nothing
end
HTMX.markdown_block(p::_TabsetPart) = !_shows_nothing(p.markdown, _ambient_audience())
filter_errors(p::_TabsetPart) = filter_errors(p.node)
_filter_errors_child(p::_TabsetPart) = _filter_errors_child(p.node)
_strip_md_chrome(p::_TabsetPart) = let markdown = _strip_md_chrome(p.markdown)
    isnothing(markdown) ? nothing : _TabsetPart(p.node, markdown)
end
_strip_md_chrome_child(p::_TabsetPart) = _strip_md_chrome(p)
_rescue_semantic!(out, p::_TabsetPart) = _rescue_semantic!(out, p.node)
function _static_walk(p::_TabsetPart, rules::_StaticRules)
    walked = _static_walk(p.node, rules)
    walked === _STATIC_REMOVED ? walked : _TabsetPart(walked, p.markdown)
end
_static_walk_child(p::_TabsetPart, rules) = _static_walk(p, rules)
_prestart_walk(p::_TabsetPart, walk, blocked) =
    _prestart_rewrap(_prestart_walk(p.node, walk, blocked), node -> _TabsetPart(node, p.markdown))
_semantic_layout_children(p::_TabsetPart) = (p.node,)

# A label that is not text reads as its words, as a master/detail row label does.
_tabset_label_text(label::AbstractString) = label
_tabset_label_text(label) = _md_label_text(Any[label])
function _tabset_markdown(label, content)
    name = _tabset_label_text(label)
    isempty(name) ? content : SemanticDisclosure(name, Any[content])
end
function _tabset_markdown(label, url::AbstractString)
    name = _tabset_label_text(label)
    string("**[", isempty(name) ? url : name, "](", url, ")**")
end

# After the value types its walk sees through (`_TabsetPart` above).
include("glossary.jl")

include("comparison.jl")

"""
    tabset(tabs::Pair...; active=1, id="tabset-\$(hash(first.(tabs)))", preload=nothing,
           url_param="tab", names=nothing)

Client-side tabs using Pico CSS nav + hyperscript.

Eager (content rendered immediately):

    tabset("Tab 1" => content1, "Tab 2" => content2; active=1)

Lazy (content is a URL string, fetched via HTMX on first tab click; the
initially active tab loads once it is visible):

    tabset("Tab 1" => "/api/tab1", "Tab 2" => "/api/tab2")

Mixed (eager + lazy):

    tabset("Summary" => render_summary(), "Details" => "/api/details")

`preload=true` starts fetching a lazy tab while the pointer rests on it (see
[`hx_link`](@ref) for the other values and what the route does with it).

The open tab lives in the page URL: a tab click replaces the URL's `tab`
parameter with the tab's name (no new history entry), and a page opened with
`?tab=<name>` — reloaded, reached with Back, or a shared link — shows that tab.
The browser does both, so the app's routes need not read `?tab=`. A tab's name
is its label lowercased, with umlauts spelled out and every other run of
characters a `-` (`"Güte der Messungen (K-40)"` → `guete-der-messungen-k-40`);
a label that is not text is named by its position. `names=["guete", "sonden", …]`
names the tabs instead. Two tabs with one name are an `ArgumentError` while the
URL or `active` picks tabs by name.
`url_param="insitu"` gives a tabset its own parameter; tabsets that share one
share its value, so give each tabset on a page its own when they should keep
their tabs apart. `url_param=nothing` leaves the URL alone. Inside a docs embed
(`.htmxo-embed`) the URL is the host page's and is left alone too.

A lazy tab the URL names loads like the initially active one: once it is
scrolled into view, so a tabset below the fold waits for the reader. A link
that should land on the tab names the tabset's `id` too, `?tab=trends#odl-tabs`;
the browser scrolls to it, and an `htmx()` page keeps it there while lazy parts
load after the page, and scrolls to a tabset that arrives in a fragment
([`url_anchor_script`](@ref)).

`active` picks the tab shown when the URL names none, by position or by name
(`active="sonden"`). Keeping the tab in the URL needs [`tabset_script`](@ref),
which [`htmx`](@ref) pages carry.

Markdown (`?plain`, [`to_markdown_string`](@ref), [`pdf_report`](@ref)) has no
tab to click, so it writes no tab bar: every tab follows in order, its label in
bold and then its content, as a [`SemanticDisclosure`](@ref) writes its label
and body. A tab whose content its reader does not see ([`private`](@ref)
content read publicly, with no stand-in) is left out with its label, and a lazy
tab is its label as a link to its address (`**[Details](/api/details)**`).
"""
function tabset(tabs::Pair...; active=1, id="tabset-$(hash(first.(tabs)))", preload=nothing,
                url_param="tab", names=nothing)
    tab_names = isnothing(url_param) && isnothing(names) && active isa Integer ? nothing :
        _tabset_checked_names(_tabset_names(tabs, names))
    active = _tabset_active_index(active, tab_names)
    h.div(; id, class="tabset", _tabset_url_attrs(url_param, preload)...)(
        _TabsetPart(h.nav(
            h.ul([
                h.li(h.a(label;
                    href="#",
                    class = i == active ? "contrast" : "secondary",
                    _="on click
                        halt the event
                        remove .contrast from <a/> in closest <nav/>
                        add .secondary to <a/> in closest <nav/>
                        remove .secondary from me
                        add .contrast to me
                        set panel to my @data-panel
                        add .u-hidden to <div.tab-panel/> in closest <div/>
                        remove .u-hidden from <div.tab-panel[data-panel='\${panel}']/> in closest <div/>
                    ",
                    data_panel="tab-$i",
                    _tabset_name_attrs(url_param, tab_names, i)...,
                    _tabset_lazy_link_attrs(content, i, active, id, preload)...,
                ))
                for (i, (label, content)) in enumerate(tabs)
            ]...)
        ), nothing),
        [_TabsetPart(_tabset_panel(content, i, active, id), _tabset_markdown(label, content))
         for (i, (label, content)) in enumerate(tabs)]...,
        _tabset_url_restore(url_param)...
    )
end

"""
    htmx_tabset(items; active=nothing, target="#content", preload=nothing, ...)

HTMX-driven tab row: each tab click fetches content from the server.
`items` is a collection of `"Label" => url` pairs.
`tab_attrs(label)` returns extra per-tab named-tuple attributes (e.g. hx_include).
`preload=true` starts fetching a tab while the pointer rests on it (see
[`hx_link`](@ref)).
The active tab is a `contrast` outline button and the others `secondary`, as in
[`nav_sidebar`](@ref); `active_class` / `inactive_class` change them.
"""
function htmx_tabset(items; active=nothing, target="#content",
                     active_class="contrast", inactive_class="secondary",
                     btn_class="outline btn-xs",
                     tab_attrs=Returns(NamedTuple()), preload=nothing)
    h.div(; class="tab-row")(
        [h.a(label; role="button",
            class=((active == label ? active_class : inactive_class) * " " * btn_class),
            hx_get=url,
            hx_target=target, hx_swap="outerHTML",
            _="on click remove .$active_class from <a/> in closest <.tab-row/> then add .$inactive_class to <a/> in closest <.tab-row/> then remove .$inactive_class from me then add .$active_class to me",
            _preload_attrs(preload)...,
            tab_attrs(label)...)
         for (label, url) in items]...
    )
end

# --- Status badge ---

# Default mapping picks the matching `u-text-*` utility class — themed via
# the `--htmxo-*` variables (see `htmxo_theme`) and works without inline styles.
const _DEFAULT_STATUS_CLASSES = (
    running   = "u-text-warning",
    finishing = "u-text-warning",
    done      = "u-text-success",
    failed    = "u-text-error",
    pending   = "u-text-muted",
)

"""
    status_badge(state::Symbol; classes=_DEFAULT_STATUS_CLASSES, label=nothing)

Render a `<span>` badge for a status state, picking a `u-text-*` utility class matching
the state. Override the display text with `label` (defaults to titlecased state name).
Pass `classes=Dict(:custom => "u-text-accent")` to remap.

    status_badge(:running)                                  # u-text-warning
    status_badge(:failed; label="Error!")                    # u-text-error "Error!"
    status_badge(:custom; classes=Dict(:custom => "u-text-accent"))
"""
function status_badge(state::Symbol; classes=_DEFAULT_STATUS_CLASSES, label=nothing)
    text = something(label, titlecase(string(state)))
    cls = get(classes, state, "u-text-muted")
    h.span(text; class=cls)
end

# --- Nav sidebar ---

"""
    nav_sidebar(items::Vector{<:Pair}; prefix="", target="#content", active_class="contrast", inactive_class="secondary", preload=nothing)

Render a Pico CSS sidebar `<aside>` with HTMX-enabled navigation links.
Each item is a `"Label" => "/path"` pair. Links use hyperscript to toggle active styling.
A click swaps the page into `target` and records its address; a Ctrl/Cmd-,
Shift- or middle-click opens it in a new tab or window instead (on an
[`htmx`](@ref) page, see [`modifier_click_script`](@ref)).
`preload=true` starts fetching a page while the pointer rests on its link (see
[`hx_link`](@ref)).

    nav_sidebar(["Overview" => "/overview", "Settings" => "/settings"]; prefix="/app")
"""
function nav_sidebar(items::Union{AbstractVector{<:Pair}, Tuple{Vararg{Pair}}}; prefix="", target="#content", active_class="contrast", inactive_class="secondary", preload=nothing)
    h.aside(
        h.nav(
            h.ul(
                [h.li(h.a(label;
                    href=prefix * path,
                    hx_get=prefix * path,
                    hx_target=target,
                    hx_push_url=prefix * path,
                    _="on click remove .$active_class from <a/> in closest <nav/> then add .$inactive_class to <a/> in closest <nav/> then remove .$inactive_class from me then add .$active_class to me",
                    class=inactive_class,
                    _preload_attrs(preload)...,
                )) for (label, path) in items]...
            )
        )
    )
end

"""
    htmxo_breadcrumb(items; target="#content", preload=nothing)

Render a Pico-styled breadcrumb `<nav>`. Each `item` is a tuple
`(label, frag_url, push_url)`. When `frag_url` is `nothing`, the segment
renders as plain text (the current page). Otherwise it's an `<a>` that issues
`hx-get=frag_url` into `target` and updates the URL bar via `hx-push-url=push_url`.
The link's `href` is the address it records — `push_url`, or `frag_url` for
`push_url="true"` — so a Ctrl/Cmd-, Shift- or middle-click opens that page in a
new tab or window (on an [`htmx`](@ref) page, see
[`modifier_click_script`](@ref)), and the link is reachable by keyboard. A
segment that records no address (`push_url` `nothing` or `"false"`) has no
`href`.
`preload=true` starts fetching a segment while the pointer rests on it (see
[`hx_link`](@ref)).

```
htmxo_breadcrumb([
    ("Home",     "/",          "/"),
    ("Projects", "/projects",  "/projects"),
    ("Detail",   nothing,      nothing),
])
```
"""
function htmxo_breadcrumb(items; target="#content", preload=nothing)
    parts = []
    for (label, frag_url, push_url) in items
        if isnothing(frag_url)
            push!(parts, h.span(label; aria_current="page"))
        else
            push!(parts, h.a(label;
                _breadcrumb_href(frag_url, push_url)...,
                hx_get=frag_url, hx_target=target, hx_swap="innerHTML",
                hx_push_url=push_url, _preload_attrs(preload)...))
        end
    end
    h.nav(parts...; class="htmxo-breadcrumb", aria_label="breadcrumb")
end

# A breadcrumb segment's `href` is the address its `hx-push-url` records.
_breadcrumb_href(frag_url, ::Nothing) = (;)
function _breadcrumb_href(frag_url, push_url)
    recorded = string(push_url)
    recorded == "false" ? (;) : (href = recorded == "true" ? frag_url : push_url,)
end

"""
    app_layout(sidebar, content; content_id="content")

Two-column app shell — sidebar `<aside>` next to a main content column. Inspired
by Pico's docs layout (CSS Grid with named areas, sticky inner nav, stacks on
mobile <1024px). `sidebar` is rendered as-is (typically [`nav_sidebar`](@ref));
`content` is wrapped in `<div class="htmxo-app-content" id=content_id>` so HTMX
swaps targeting `#content` work out of the box.

Sidebar width defaults to `12rem` via the `--htmxo-sidebar-width` CSS variable;
apps can override it in their own scoped style:

    .htmxo-app-layout { --htmxo-sidebar-width: 10rem; }

```
__page__(content) = htmx(
    app_layout(
        nav_sidebar(["Table" => "/", "Gallery" => "/gallery"]),
        content,
    );
    pico_version="2",
)
```
"""
function app_layout(sidebar, content; content_id="content")
    h.div(; class="htmxo-app-layout")(
        sidebar,
        h.main(content; id=content_id),
    )
end

"""
    editor_styles()

CSS for [`editor_form`](@ref): monospace `<textarea>`/`<input>` editor body
(`.htmxo-editor-input`) and the Save/Cancel button row (`.htmxo-editor-actions`).
Scoped class names, no global selectors. Auto-included by [`htmx`](@ref); inject
manually via `extra_head` if you build your own `<head>`.
"""
editor_styles() = h.style(Raw("""
@layer htmxo {
.htmxo-editor-input {
    font-family: monospace;
    font-size: 0.85em;
    width: 100%;
}
.htmxo-editor-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}
}
"""))

"""
    editor_form(; id, post_url, content="", version="", ...) -> Node

Inline edit form for text content. Renders a `<textarea>` (default) or text
`<input>` with Save/Cancel buttons and Escape-to-cancel. On submit, POSTs to
`post_url` with form fields `content` (or `field_name`) and `version`; the
response is swapped into `#target_id` via `hx-swap=\$swap`.

`version` is a hidden conflict token — echoed back by the save handler so it
can detect concurrent edits. Empty string is fine for apps that don't check.

Cancel:
- `cancel_url` → Cancel issues `hx-get` to that URL.
- `cancel_onclick` → Cancel runs that JS (e.g. `"this.closest('#\$id').remove()"`).
Exactly one must be given.

# Arguments
- `id`                   — container/form element id.
- `tag`                  — outer tag (default `h.div`).
- `class`                — outer element class.
- `post_url`             — URL for Save.
- `target_id`            — `hx-target` for Save response (default `id`).
- `swap`                 — `hx-swap` value (default `"outerHTML"`).
- `content`              — initial content.
- `version`              — hidden version/hash token for conflict detection.
- `field_name`           — form field name for the edited text (default `"content"`).
- `input`                — `:textarea` or `:text`.
- `rows`                 — textarea rows.
- `placeholder`          — input placeholder.
- `label`                — optional label rendered above the editor.
- `save_label`           — submit-button label (default `"Save"`).
- `cancel_url`           — URL for Cancel (`hx-get`).
- `cancel_onclick`       — inline JS for Cancel.
"""
function editor_form(;
    id,
    tag             = h.div,
    class           = "",
    post_url,
    target_id       = id,
    swap            = "outerHTML",
    content         = "",
    version         = "",
    field_name      = "content",
    input           = :textarea,
    rows            = 15,
    placeholder     = "",
    label           = nothing,
    save_label      = "Save",
    cancel_url      = nothing,
    cancel_onclick  = nothing,
)
    (cancel_url === nothing) == (cancel_onclick === nothing) &&
        error("editor_form: provide exactly one of `cancel_url` or `cancel_onclick`")

    input_node = input === :textarea ?
        h.textarea(content; name=field_name, rows=string(rows), class="htmxo-editor-input") :
        input === :text ?
            h.input(; type="text", name=field_name, value=content,
                      placeholder, class="htmxo-editor-input") :
            error("editor_form: `input` must be `:textarea` or `:text`, got $(repr(input))")

    cancel_btn = cancel_url !== nothing ?
        h.button("Cancel";
            type="button", class="secondary outline",
            data_cancel="",
            hx_get=cancel_url, hx_target="#$target_id", hx_swap=swap) :
        h.button("Cancel";
            type="button", class="secondary outline",
            data_cancel="",
            onclick=cancel_onclick)

    tag(; id, class,
          onkeydown="if(event.key==='Escape'){this.querySelector('[data-cancel]').click()}")(
        isnothing(label) ? "" : h.label(label),
        h.form(; hx_post=post_url, hx_target="#$target_id", hx_swap=swap)(
            input_node,
            h.input(; type="hidden", name="version", value=version),
            h.div(; class="htmxo-editor-actions")(
                h.button(save_label; type="submit"),
                cancel_btn,
            ),
        ),
    )
end

# ── Git-backed versioned content store ──────────────────────────────────────

# Parse "Name <email@example.com>" → (name, email). Fallback email keeps
# LibGit2.Signature happy when callers pass a bare name.
function _parse_author(s::AbstractString)
    m = match(r"^(.*?)\s*<(.+?)>\s*$", s)
    m === nothing ? (String(s), "noreply@localhost") : (String(m[1]), String(m[2]))
end

# --- File-based galleries ---

"""
    parse_gallery_metadata(raw::AbstractString) -> Dict{String,String}

Parse `# key: value` header lines from a Julia source file. Stops at
the first non-comment line. Comment lines without a `:` are ignored.
Keys are lowercased. Standard keys: `title`, `description`, `id`,
`section`. Apps may read additional keys directly from `item.metadata`.
"""
function parse_gallery_metadata(raw::AbstractString)
    md = Dict{String,String}()
    for line in split(raw, '\n')
        s = lstrip(line)
        if isempty(strip(line))
            isempty(md) ? continue : break
        end
        startswith(s, "#") || break
        body = strip(s[2:end])
        idx = findfirst(==(':'), body)
        isnothing(idx) && continue
        key = lowercase(strip(body[1:idx-1]))
        val = strip(body[idx+1:end])
        isempty(key) && continue
        md[String(key)] = String(val)
    end
    md
end

# Strip the leading metadata block (comment + blank lines) and return
# the rest of the file body verbatim. Used as `code_string` so docs can
# show "the actual code" without the docs frontmatter.
function _strip_gallery_header(raw::AbstractString)
    lines = split(raw, '\n')
    i = 1
    while i <= length(lines)
        s = lstrip(lines[i])
        if isempty(strip(lines[i]))
            i += 1
        elseif startswith(s, "#")
            body = strip(s[2:end])
            occursin(':', body) || break  # comment without `key:` ends the header
            i += 1
        else
            break
        end
    end
    join(lines[i:end], '\n')
end

"""
    GalleryItem(path)

Single gallery entry parsed from a Julia source file at `path`. Reads
the metadata header (`# key: value` lines) and captures the rest of the
file as `code_string`. The body is `Base.include`-able by the app so it
can be eval'd to produce a value (Vega-Lite spec, Stan model, formula
text, …) the app's renderer turns into HTML.

Standard properties:

  * `path`         — absolute file path.
  * `id`           — defaults to filename without extension; override via `# id: …`.
  * `title`        — defaults to `id`; override via `# title: …`.
  * `description`  — `# description: …` or empty.
  * `section`      — `# section: …` or the parent directory's basename.
  * `metadata`     — full parsed header dict.
  * `code_string`  — file body with the header stripped.

`Base.show(io, MIME"text/markdown"(), item)` produces the agent-friendly
view: `## title \\n *description* \\n ```julia\\ncode\\n``` `.
"""
@dynamicstruct struct GalleryItem
    path::String
    raw = read(path, String)
    metadata = parse_gallery_metadata(raw)
    id = get(metadata, "id", first(splitext(basename(path))))
    title = get(metadata, "title", id)
    description = get(metadata, "description", "")
    section = get(metadata, "section", basename(dirname(path)))
    # `# tags: foo, bar baz` — comma- or whitespace-separated. Empty if
    # the header doesn't declare any. Drives both the searchable text
    # corpus (so `tag:` matches without users having to know the field)
    # and any future tag-chip filter UI.
    tags = String[String(t) for t in split(get(metadata, "tags", ""), r"[,\s]+"; keepempty=false)]
    code_string = _strip_gallery_header(raw)
end

function Base.show(io::IO, ::MIME"text/markdown", item::GalleryItem)
    println(io, "## ", item.title)
    println(io)
    isempty(item.description) || (println(io, "*", item.description, "*"); println(io))
    println(io, "```julia")
    print(io, rstrip(item.code_string))
    println(io)
    println(io, "```")
end

# `_section.md` per directory: either a `# Title` first-line markdown,
# a `title: Foo` key/value, or the file content interpreted as the
# section title. Returns `(section_id => title)` for each subdir that
# has a `_section.md`. Subdir basename is the section id; matches the
# default `section` for items without an explicit `# section:` header.
function _read_section_title(path::AbstractString)
    text = read(path, String)
    for line in split(text, '\n')
        s = strip(line)
        isempty(s) && continue
        # `# Foo` heading
        if startswith(s, "#")
            body = strip(s[2:end])
            startswith(body, "#") && (body = strip(lstrip(body, '#')))
            isempty(body) && continue
            occursin(':', body) || return String(body)
            # `title: Foo` key/value disguised as a comment
            idx = findfirst(==(':'), body)
            key = lowercase(strip(body[1:idx-1]))
            key == "title" && return String(strip(body[idx+1:end]))
            continue
        end
        # `title: Foo` plain key/value
        if occursin(':', s)
            idx = findfirst(==(':'), s)
            key = lowercase(strip(s[1:idx-1]))
            key == "title" && return String(strip(s[idx+1:end]))
        end
        # First non-empty non-comment line is the title
        return String(s)
    end
    return ""
end

# Walk a gallery directory, return (items::Vector{GalleryItem},
# section_titles::Dict{section_id => title}). Items are sorted by
# (section, filename) so the gallery has stable order.
function _collect_gallery(gallery_dir::AbstractString)
    items = GalleryItem[]
    section_titles = Dict{String,String}()
    for (root, dirs, files) in walkdir(gallery_dir)
        sort!(files)
        sort!(dirs)
        for f in files
            if f == "_section.md"
                sec_id = basename(root)
                section_titles[sec_id] = _read_section_title(joinpath(root, f))
            elseif endswith(f, ".jl")
                push!(items, GalleryItem(joinpath(root, f)))
            end
        end
    end
    items, section_titles
end

"""
    Gallery(gallery_dir)

Walks `gallery_dir` recursively and builds one `GalleryItem` per `.jl`
file. Reads section titles from `_section.md` files in each
subdirectory (first non-empty line, or `title: …` key/value).

Items are sorted by `(section, filename)` for stable gallery order.

`find_item(g, id)` returns the item with the given id, or `nothing`.
`section_items(g, section)` returns the items belonging to that section.
"""
@dynamicstruct struct Gallery
    gallery_dir::String
    _walk = _collect_gallery(gallery_dir)
    items = first(_walk)
    section_titles = last(_walk)
end

function find_item(g::Gallery, id::AbstractString)
    for it in g.items
        it.id == id && return it
    end
    nothing
end

section_items(g::Gallery, section::AbstractString) =
    filter(it -> it.section == section, g.items)

"""
    gallery_grid(items; section_titles=Dict(), card_renderer=default_gallery_card,
                        controls=true, search=true, pagination=true,
                        page_size=25, page_sizes=(10, 25, 50, 100, 0),
                        search_placeholder="Search (regex; literal fallback)…",
                        tag_filters=false, tag_match=:all)

Render a single-column grid of `card_renderer(item)` cards, grouped by
section. Sections appear in directory-traversal order (preserved by
`Gallery.items`). The section heading uses
`section_titles[section_id]` if present, falling back to the bare
section id (typically the directory basename).

When `controls=true` (default), the result is wrapped in a
`.htmxo-gallery-root` that also carries a sticky toolbar with a search
box and pagination controls. The toolbar is driven by an inline
controller script that sets `data-search-hidden` / `data-page-hidden`
on cards (and `data-empty` on sections whose visible-card count drops
to zero). The controller works identically in:

  * Live HTMXObjects pages (browser executes the inline `<script>` as
    part of normal page load).
  * Recorded fragments embedded into VitePress docs (HTMX innerHTML
    swaps don't auto-execute scripts, but `setupHtmxoEmbed` from
    `htmxo-embed.ts` re-executes inline scripts inside `.htmxo-embed`
    after every swap so the controller wires up there too).
  * Static exports (`static_transform`, `record!`): the controls are
    plain buttons and inputs, so they run without a server.

`tag_filters=true` adds a row of tag chips under each section heading:
one `<button aria-pressed>` per distinct tag of that section's items
(`GalleryItem.tags`, the `# tags:` header), in order of first
appearance. Pressing chips filters only that section's cards, matched
against each card's `data-tags` (space-separated). With
`tag_match=:all` (default) a card must carry every pressed tag, so each
chip narrows, and a chip that would leave no card is disabled; with
`tag_match=:any` a card needs one of them. Tags combine with the search
box (a card must pass both), and a section with no card left is hidden,
as with search. A section without tags gets no chips.

Each section carries `id` = its section key (`<section id="2-software"
data-section="2-software">`), as each card carries its card id, so a page's
nav links reach it with `href="#2-software"`. A section key equal to a card
id would put one id on two elements and throws an `ArgumentError`. With the
controls, a link to a section none of whose cards shows reveals it: the
search is cleared only if it hides all of the section's cards, the section's
chips are released only if they then still do, and the page turns to its
first card. A link to a card reveals the card. Both also apply when a page
opens at the link, and a target scrolls to just below the sticky toolbar.

A custom `card_renderer` builds its card with [`gallery_card`](@ref):
the controller only sees `<article>` children of a section, and reads
the `id`, `data-tags` and `data-search-text` that `gallery_card` sets.

The gallery carries its own stylesheet ([`htmxo_gallery_styles`](@ref)) as
the first child of `.htmxo-gallery`, in both forms: it is what hides the
cards the controller marks, so search, pagination and chips work on any
page without head setup. An app that restyles the gallery from its
`<head>` needs a selector more specific than the sheet's, since the sheet
comes later in the document.

URL state: the search query mirrors `?q=`, the current page mirrors
`?page=`, the page size mirrors `?ps=`, and a section's pressed tags
mirror `?tag.<section>=a,b` — so a deep-link to a filtered/paginated
view round-trips.

Pass `controls=false` to opt out and recover the original bare
`.htmxo-gallery` `<div>` (used by apps that want to compose their own
toolbar); its tag chips (if any) then need the app's own
`.htmxo-gallery-root` and [`gallery_controls_script`](@ref).

In Markdown (`?plain`) the toolbar, the chips and the empty-state line
are dropped; the sections and cards remain.

Standard CSS classes: `htmxo-gallery-root`, `htmxo-gallery-toolbar`,
`htmxo-gallery-search`, `htmxo-gallery-pagination`, `htmxo-gallery`,
`htmxo-gallery-section`, `htmxo-gallery-section-heading`,
`htmxo-gallery-card`, `htmxo-gallery-card-title`,
`htmxo-gallery-card-description`, `htmxo-gallery-card-code`.
"""
function gallery_grid(items::AbstractVector{GalleryItem};
        section_titles::AbstractDict=Dict{String,String}(),
        card_renderer=default_gallery_card,
        controls::Bool=true,
        search::Bool=true,
        pagination::Bool=true,
        page_size::Int=25,
        page_sizes=(10, 25, 50, 100, 0),
        search_placeholder::AbstractString="Search (regex; literal fallback)…",
        tag_filters::Bool=false,
        tag_match::Symbol=:all)
    tag_match in (:all, :any) || throw(ArgumentError(
        "gallery_grid tag_match must be :all or :any; got $(repr(tag_match))"))
    seen = String[]
    groups = Dict{String,Vector{GalleryItem}}()
    for it in items
        if !haskey(groups, it.section)
            push!(seen, it.section)
            groups[it.section] = GalleryItem[]
        end
        push!(groups[it.section], it)
    end
    # A section's `id` is its key, as a card's is its card id; one id on two
    # elements would send a `#id` link to whichever comes first.
    clash = findfirst(it -> haskey(groups, it.id), items)
    isnothing(clash) || throw(ArgumentError(
        "gallery_grid: the section \"$(items[clash].id)\" and the card " *
        "$(repr(items[clash].path)) would share the id \"$(items[clash].id)\"; " *
        "rename the section or give the card an `# id:` header"))
    sections = map(seen) do sec
        title = get(section_titles, sec, sec)
        chips = tag_filters ? _gallery_tag_chips(groups[sec], tag_match) : ()
        h.section(; id=sec, data_section=sec)(
            h.h3(title),
            chips...,
            [card_renderer(it) for it in groups[sec]]...,
        )
    end
    inner = h.div(; class="htmxo-gallery")(htmxo_gallery_styles(), sections...)
    (controls && (search || pagination || tag_filters)) || return inner
    h.div(; class="htmxo-gallery-root")(
        (search || pagination ? (html_only(gallery_toolbar(; search, pagination,
            page_size, page_sizes, search_placeholder)),) : ())...,
        inner,
        html_only(h.div("No items match the current filter."; class="htmxo-gallery-empty")),
        h.script(Raw(gallery_controls_script())),
    )
end

# One section's tag chips: a row of toggles, one per distinct tag, right
# under the section heading. Not `role="group"`: Pico styles that as a
# joined button group whose children stretch. HTML only; the controller
# reads `data-tag` / `aria-pressed` and the row's `data-tag-match`.
function _gallery_tag_chips(items, tag_match::Symbol)
    tags = unique(Iterators.flatten(it.tags for it in items))
    isempty(tags) && return ()
    (html_only(h.div(; data_role="tag-filters", data_tag_match=String(tag_match))(
        (h.button(t; type="button", data_tag=t, aria_pressed="false") for t in tags)...)),)
end

"""
    gallery_toolbar(; search=true, pagination=true,
                       page_size=25, page_sizes=(10, 25, 50, 100, 0),
                       search_placeholder="Search…")

Build the gallery toolbar fragment used by `gallery_grid(; controls=true)`.
Exposed standalone so apps that compose their own gallery wrapper can
reuse the same controls. `0` in `page_sizes` is shown as "all" — the
controller reads `parseInt(value)` and treats `<=0` as "no pagination".
"""
function gallery_toolbar(; search::Bool=true, pagination::Bool=true,
        page_size::Int=25, page_sizes=(10, 25, 50, 100, 0),
        search_placeholder::AbstractString="Search (regex; literal fallback)…")
    parts = []
    search && push!(parts, h.input(;
        type="search",
        placeholder=search_placeholder,
        autocomplete="off"))
    if pagination
        # `selected` is a boolean HTML attribute — its mere presence
        # selects, regardless of value. Only emit it on the matching
        # option (and via `selected="selected"` so renderers that
        # require a string value still emit the attribute).
        _opt(label, value) = (value == string(page_size)) ?
            h.option(label; value=value, selected="selected") :
            h.option(label; value=value)
        ps_options = [v == 0 ? _opt("all", "0") : _opt(string(v), string(v))
                      for v in page_sizes]
        push!(parts, h.div(; class="htmxo-gallery-pagination")(
            h.span("Page size: "),
            h.select(; data_role="page-size")(ps_options...),
            h.button("←"; type="button", data_role="prev",
                     aria_label="Previous page"),
            h.span("Page 1"; data_role="page-info"),
            h.button("→"; type="button", data_role="next",
                     aria_label="Next page"),
        ))
    end
    h.div(; class="htmxo-gallery-toolbar")(parts...)
end

# Inline controller for the gallery toolbar. Emitted as a `<script>` so
# it runs both:
#   * As part of normal page load (live app), and
#   * As part of an htmx swap into `.htmxo-embed` — but only because
#     `setupHtmxoEmbed` re-executes inline scripts after the swap, since
#     `innerHTML` assignment does not run `<script>` tags by default.
#
# The controller is scoped to `document.currentScript.closest('.htmxo-gallery-root')`
# so multiple galleries on the same page get independent state.
"""
    gallery_controls_script() -> String

The inline JS that wires up the gallery toolbar. Returned as a string
so it can be embedded as `h.script(gallery_controls_script())`. Idempotent:
running it multiple times against the same root is harmless (each run
re-binds listeners on the same elements; classes are re-derived from
the current input/select state).
"""
gallery_controls_script() = """
(() => {
    // Initialize every uninitialized `.htmxo-gallery-root` on the page,
    // not just the closest one to the current script. htmx may execute
    // a swapped `<script>` body via `eval` (no `currentScript`) or by
    // re-inserting it elsewhere, so closest-based scoping is fragile.
    // Instead each script invocation scans the document and wires up
    // any roots it finds; the `data-htmxo-controls-init` sentinel keeps
    // re-runs idempotent.
    const initRoot = (root) => {
        if (root.dataset.htmxoControlsInit === '1') return;
        root.dataset.htmxoControlsInit = '1';
        const gallery = root.querySelector('.htmxo-gallery');
        const search  = root.querySelector('.htmxo-gallery-toolbar input[type="search"]');
        const psSel   = root.querySelector('[data-role="page-size"]');
        const prevBtn = root.querySelector('[data-role="prev"]');
        const nextBtn = root.querySelector('[data-role="next"]');
        const pageInfo= root.querySelector('[data-role="page-info"]');
        const empty   = root.querySelector('.htmxo-gallery-empty');
        if (!gallery) return;

        const cards    = () => Array.from(gallery.querySelectorAll(':scope > section > article, :scope > article'));
        const sections = () => Array.from(gallery.querySelectorAll(':scope > section'));
        // Per-section tag chips (`gallery_grid(...; tag_filters=true)`).
        const chipGroups = () => Array.from(gallery.querySelectorAll(':scope > section > [data-role="tag-filters"]'));
        const chipsOf  = group => Array.from(group.querySelectorAll('button[data-tag]'));
        const params   = new URLSearchParams(window.location.search);
        let page = Math.max(0, (parseInt(params.get('page') || '1', 10) || 1) - 1);

        if (search && params.get('q'))  search.value = params.get('q');
        if (psSel  && params.get('ps')) psSel.value  = params.get('ps');
        chipGroups().forEach(group => {
            const wanted = (params.get('tag.' + group.parentElement.dataset.section) || '')
                .split(',').filter(Boolean);
            chipsOf(group).forEach(b => b.setAttribute('aria-pressed',
                String(wanted.includes(b.dataset.tag))));
        });

        const haystack = c => (c.dataset.searchText
            || (c.textContent || '').toLowerCase().replace(/\\s+/g, ' ').trim());
        const cardTags = c => (c.dataset.tags || '').split(/\\s+/).filter(Boolean);
        const pressed  = group => chipsOf(group)
            .filter(b => b.getAttribute('aria-pressed') === 'true').map(b => b.dataset.tag);
        const tagsPass = (group, tags) => {
            const want = pressed(group);
            if (!want.length) return true;
            return group.dataset.tagMatch === 'any'
                ? want.some(t => tags.includes(t))
                : want.every(t => tags.includes(t));
        };
        const filtered = c => c.hasAttribute('data-search-hidden') || c.hasAttribute('data-tag-hidden');

        const setAttr = (el, name, on) => {
            if (on) el.setAttribute(name, ''); else el.removeAttribute(name);
        };

        const applyFilter = () => {
            const raw = (search && search.value || '').trim();
            let re = null, lit = '';
            if (raw) {
                try { re = new RegExp(raw, 'i'); }
                catch (_) { lit = raw.toLowerCase(); }
            }
            if (search) {
                if (lit) search.dataset.mode = 'literal';
                else delete search.dataset.mode;
            }
            cards().forEach(c => {
                const hay = haystack(c);
                const show = !raw
                    || (re && re.test(hay))
                    || (lit && hay.includes(lit));
                setAttr(c, 'data-search-hidden', !show);
                setAttr(c, 'data-tag-hidden', false);
            });
            chipGroups().forEach(group => {
                const own = Array.from(group.parentElement.querySelectorAll(':scope > article'));
                own.forEach(c => setAttr(c, 'data-tag-hidden', !tagsPass(group, cardTags(c))));
                // A chip is offered while pressing it could still show a
                // card that passes the search: under `all` among the cards
                // the pressed chips leave, under `any` among all of them.
                const pool = own.filter(c => !c.hasAttribute('data-search-hidden')
                    && (group.dataset.tagMatch === 'any' || !c.hasAttribute('data-tag-hidden')));
                chipsOf(group).forEach(b => {
                    b.disabled = b.getAttribute('aria-pressed') !== 'true'
                        && !pool.some(c => cardTags(c).includes(b.dataset.tag));
                });
            });
        };

        const applyPagination = () => {
            const visible = cards().filter(c => !filtered(c));
            const ps = psSel ? (parseInt(psSel.value, 10) || 0) : 0;
            const total = visible.length;
            const pages = ps > 0 ? Math.max(1, Math.ceil(total / ps)) : 1;
            if (page >= pages) page = pages - 1;
            if (page < 0)      page = 0;
            visible.forEach((c, i) => {
                const inPage = ps <= 0 || (i >= page * ps && i < (page + 1) * ps);
                setAttr(c, 'data-page-hidden', !inPage);
            });
            // Filtered cards must not also carry data-page-hidden — when
            // the search or a chip clears, those cards re-become candidates
            // and pagination needs to re-decide their fate.
            cards().filter(filtered)
                   .forEach(c => c.removeAttribute('data-page-hidden'));
            if (pageInfo) pageInfo.textContent =
                'Page ' + (page + 1) + ' / ' + pages + ' \\u2022 ' + total
                + (total === 1 ? ' item' : ' items');
            if (prevBtn) prevBtn.disabled = page === 0;
            if (nextBtn) nextBtn.disabled = page >= pages - 1;
            if (empty)   empty.hidden = total !== 0;
        };

        const applySectionVisibility = () => sections().forEach(sec => {
            const allCards = sec.querySelectorAll(':scope > article');
            const anyVisible = Array.from(allCards).some(c =>
                !filtered(c) && !c.hasAttribute('data-page-hidden'));
            setAttr(sec, 'data-empty', !anyVisible);
        });

        const refresh = () => { applyFilter(); applyPagination(); applySectionVisibility(); };

        const syncUrl = () => {
            // URL sync only makes sense for top-level pages (the user's
            // address bar is the gallery's address). Inside an
            // `.htmxo-embed` the URL belongs to the docs host and we
            // must not stomp it.
            if (root.closest('.htmxo-embed')) return;
            const url = new URL(window.location.href);
            const q = (search && search.value || '').trim();
            if (q) url.searchParams.set('q', q); else url.searchParams.delete('q');
            if (page > 0) url.searchParams.set('page', String(page + 1));
            else          url.searchParams.delete('page');
            chipGroups().forEach(group => {
                const key = 'tag.' + group.parentElement.dataset.section;
                const on = pressed(group);
                if (on.length) url.searchParams.set(key, on.join(','));
                else           url.searchParams.delete(key);
            });
            history.replaceState(null, '', url);
        };

        if (search)  search.addEventListener('input',  () => { page = 0; refresh(); syncUrl(); });
        if (psSel)   psSel.addEventListener('change',  () => { page = 0; refresh(); syncUrl(); });
        if (prevBtn) prevBtn.addEventListener('click', () => { page--;   refresh(); syncUrl(); });
        if (nextBtn) nextBtn.addEventListener('click', () => { page++;   refresh(); syncUrl(); });
        chipGroups().forEach(group => chipsOf(group).forEach(b => b.addEventListener('click', () => {
            b.setAttribute('aria-pressed', String(b.getAttribute('aria-pressed') !== 'true'));
            page = 0; refresh(); syncUrl();
        })));

        // A link scrolls its target to the top of the window, under the sticky
        // toolbar. `--htmxo-gallery-toolbar-h` (the sheet's
        // `scroll-margin-top` on sections and cards) is the toolbar's height
        // plus the gap it keeps above the first section.
        const toolbar = root.querySelector('.htmxo-gallery-toolbar');
        const setToolbarHeight = () => root.style.setProperty('--htmxo-gallery-toolbar-h',
            (toolbar ? toolbar.offsetHeight + (parseFloat(getComputedStyle(toolbar).marginBottom) || 0) : 0) + 'px');
        setToolbarHeight();
        if (toolbar && window.ResizeObserver) new ResizeObserver(setToolbarHeight).observe(toolbar);

        const chipGroupOf = sec => sec.querySelector(':scope > [data-role="tag-filters"]');
        const release = group => chipsOf(group).forEach(b => b.setAttribute('aria-pressed', 'false'));
        // Turn to the page holding `card`, one the filters leave.
        const turnTo = card => {
            const ps = psSel ? (parseInt(psSel.value, 10) || 0) : 0;
            const idx = cards().filter(c => !filtered(c)).indexOf(card);
            if (idx >= 0 && ps > 0) page = Math.floor(idx / ps);
        };
        // Hash navigation: clicking a card title's `#id` anchor must
        // reveal the card even if it was filtered or paginated out.
        // Reset search and the card's section chips, recompute filters,
        // and jump to the page that contains the card.
        const revealCard = card => {
            if (search && search.value) search.value = '';
            const group = chipGroupOf(card.parentElement);
            if (group && !tagsPass(group, cardTags(card))) release(group);
            applyFilter();
            turnTo(card);
        };
        // A link to a section's `#key` reveals it only when none of its
        // cards shows: it clears the search only if that hides all of them,
        // then releases the section's chips only if they still do, and turns
        // to the page of its first card. Returns whether anything changed.
        const revealSection = sec => {
            const own = Array.from(sec.querySelectorAll(':scope > article'));
            if (own.some(c => !filtered(c) && !c.hasAttribute('data-page-hidden'))) return false;
            if (search && search.value && own.every(c => c.hasAttribute('data-search-hidden'))) {
                search.value = ''; applyFilter();
            }
            const group = chipGroupOf(sec);
            if (group && own.every(c => filtered(c))) { release(group); applyFilter(); }
            const first = own.find(c => !filtered(c));
            if (first) turnTo(first);
            return true;
        };
        const jumpToHash = () => {
            const id = decodeURIComponent((window.location.hash || '').slice(1));
            if (!id) return;
            const sel = 'article[data-id="' + CSS.escape(id) + '"], #' + CSS.escape(id);
            const target = gallery.querySelector(sel);
            if (!target) return;
            const changed = sections().includes(target) ? revealSection(target)
                : (revealCard(target.closest('article') || target), true);
            if (changed) { applyPagination(); applySectionVisibility(); syncUrl(); }
            target.scrollIntoView({ block: 'start' });
        };
        window.addEventListener('hashchange', jumpToHash);

        refresh();
        // A page opened at a section's or a card's `#id` shows it as well.
        jumpToHash();
    };
    document.querySelectorAll('.htmxo-gallery-root').forEach(initRoot);
})();
"""

"""
    gallery_card(item::GalleryItem; attrs...)

The `<article>` of one gallery card, carrying what the controller of
[`gallery_grid`](@ref) reads: `id` and `data-id` (an `#id` link reveals
the card), `data-section`, `data-tags` (the tag chips) and
`data-search-text` (the search corpus: title, description, tags, section
and id, lowercased). Call the result with the card's content. Further
keywords become attributes, and one named like these replaces it — e.g.
`data_search_text=` for a corpus of your own.

    card_renderer = item -> gallery_card(item)(
        h.h4(h.a(item.title; href="#" * item.id)), my_plot(item))
"""
gallery_card(item::GalleryItem; attrs...) = h.article(;
    id=item.id,
    data_id=item.id,
    data_section=item.section,
    data_tags=join(item.tags, " "),
    # Lowercased so the controller can `includes()` directly.
    data_search_text=lowercase(strip(string(
        item.title, ' ', item.description, ' ',
        join(item.tags, ' '), ' ', item.section, ' ', item.id))),
    attrs...)

"""
    default_gallery_card(item::GalleryItem)

Default card layout: title heading + description (always visible) +
inline source code block. No collapsible details — important info
is visible directly. Apps that add Vega-Lite plots, PPC plots, etc.
build their own on [`gallery_card`](@ref):
`card_renderer = item -> gallery_card(item)(h.h4(item.title), my_render(item))`.
"""
default_gallery_card(item::GalleryItem) = gallery_card(item)(
    h.h4(
        h.a(item.title; href="#" * item.id),
    ),
    isempty(item.description) ? h.span() :
        h.p(item.description),
    h.pre(h.code(item.code_string)),
)

"""
    htmxo_gallery_styles()

`<style>` block with the canonical gallery layout: single-column,
flat (no card frame), proper heading hierarchy, themed via `--htmxo-*`
tokens. It also hides the cards and sections the gallery controller
marks. [`gallery_grid`](@ref) carries it itself, so all HTMXO apps
present galleries the same way; a gallery an app composes from its own
markup includes it via `extra_head` in `htmx(...)`, which a linked shell
(`runtime=:linked`) links like the other page helpers.

Source of truth is
`HTMXObjects/assets/vitepress/htmxo-gallery.css` — same file is
imported by `htmxo-embed.ts` so the docs-embedded fragment matches.
"""
htmxo_gallery_styles() = h.style(Raw(replace(
    read(joinpath(_VITEPRESS_ASSETS_DIR, "htmxo-gallery.css"), String),
    # Without its comments: every gallery carries the sheet, where they are
    # dead bytes (about 40 %), and inside an inline <style> a comment's
    # markup example could end the element early.
    r"/\*.*?\*/"s => "")))

"""
    htmxo_syntax_head() -> Tuple

The two runtime blocks that highlight code, [`syntax_styles`](@ref) and
[`syntax_script`](@ref). Every [`htmx`](@ref) page carries both, so a copy in
its `extra_head` is left out; a hand-built head adds them together with the
PrismJS template from [`vendor_head`](@ref)`(base; packages=(:prism,))`.

The same token CSS gets shipped to docs themes via
`vitepress_theme_install` (alongside `htmxo-embed.ts`/`htmxo-gallery.css`)
so embedded fragments inherit the theme-aware coloring without
needing the script tags from the fragment to execute (which they
wouldn't, since `innerHTML` swaps don't run scripts).
"""
htmxo_syntax_head() = (syntax_styles(), syntax_script())

# Blob sha of `relpath` at revspec `rev` — a commit sha, `"HEAD"`, `"<sha>^2"`.
# `""` when the revision does not resolve or the path does not exist there: an
# unborn file, a deleted one, or a root commit's parent.
function _blob_sha_at(repo, rev::AbstractString, relpath::AbstractString)
    try
        obj = LibGit2.GitObject(repo, rev * ":" * relpath)
        try
            string(LibGit2.GitHash(obj))
        finally
            close(obj)
        end
    catch err
        err isa LibGit2.GitError || rethrow()
        ""
    end
end

# Parent commit shas of `sha`, in order; empty for a root commit. Julia's
# LibGit2 wrapper exposes no parent accessor, so probe the `<sha>^1`, `<sha>^2`,
# … revspecs until one stops resolving.
function _parent_shas(repo, sha::AbstractString)
    out = String[]
    i = 1
    while true
        obj = try
            LibGit2.GitObject(repo, sha * "^" * string(i))
        catch err
            err isa LibGit2.GitError || rethrow()
            break
        end
        try
            push!(out, string(LibGit2.GitHash(obj)))
        finally
            close(obj)
        end
        i += 1
    end
    out
end

# Replace the file at `path` with `content` without ever exposing a partial
# file: write a sibling temp file, then rename it over `path`. A concurrent
# reader opens either the old file or the new one, each complete. Writing in
# place truncated the file first, so a plain `read`/`YAML.load_file` racing a
# write saw a cut-off document (snag `gitrepo-editor-w-0ed7cd16`).
#
# The temp file sits in the target's directory (a rename is atomic only within
# one filesystem), is hidden and ends in `.tmp`, so a reader listing `*.yml`
# or `*.md` never picks one up, and takes over an existing file's permissions.
function _replace_file!(path::AbstractString, content)
    dir = dirname(path)
    mkpath(isempty(dir) ? "." : dir)
    tmp = joinpath(dir, "." * basename(path) * "." *
                        Random.randstring(Random.RandomDevice(), 12) * ".tmp")
    try
        write(tmp, content)
        isfile(path) && chmod(tmp, filemode(path) & 0o7777)
        _rename_over!(tmp, path)
    catch
        rm(tmp; force=true)
        rethrow()
    end
    nothing
end

# rename(2) replaces `dst` atomically on POSIX. Windows refuses to replace a
# file another handle holds open, Julia's own readers included, so retry there
# for a few reads' worth of time (≈3 s in all) before the error propagates.
_rename_over!(src, dst) = Sys.iswindows() ?
    retry(() -> Base.Filesystem.rename(src, dst);
          delays=ExponentialBackOff(; n=12, first_delay=0.005, max_delay=0.5, factor=2.0))() :
    Base.Filesystem.rename(src, dst)

"""
    GitRepo(path; author="HTMXObjects <noreply@localhost>")

A `@dynamicstruct` owning a directory managed as a git repo — the backend
for [`EditorRoutes`](@ref). Auto-`git init`s on first access.

`editor(relpath; default_content="")` returns a per-file handle with
`current_content()`, `current_version()`, `versions()`, `read_version(sha)`,
`write!(content; version, message)` and `update!(f; message)`. Mutations are
serialised by a per-instance `ReentrantLock`, and every write replaces the file
atomically (a sibling temp file renamed over it), so any reader of the file —
`current_content()` or a plain `read`/`YAML.load_file` of
`joinpath(path, relpath)` — sees either the previous or the new complete
content, never a partial one. No lock is needed to read.
"""
@dynamicstruct struct GitRepo
    path::String
    author::String = "HTMXObjects <noreply@localhost>"
    _lock = ReentrantLock()

    _ensure() = begin
        if !isdir(joinpath(path, ".git"))
            mkpath(path)
            close(LibGit2.init(path))
        end
        nothing
    end

    # `@fresh`: `LibGit2.Signature(name, email)` stamps the current time, so a
    # memoized signature dated every later commit with the first one's second
    # (snag `gitrepo-editor-c-710f9834`).
    @fresh _signature() = begin
        name, email = _parse_author(author)
        LibGit2.Signature(name, email)
    end

    @fresh read_blob(spec) = begin
        _ensure()
        repo = LibGit2.GitRepo(path)
        try
            obj = LibGit2.GitObject(repo, spec)
            try
                obj isa LibGit2.GitBlob || error("GitRepo.read_blob: $(spec) is not a blob")
                String(LibGit2.rawcontent(obj))
            finally
                close(obj)
            end
        finally
            close(repo)
        end
    end

    @struct editor(relpath; default_content="") = begin
        abs_path = joinpath(path, relpath)

        # Every git-state-dependent call below is `@fresh`: DynamicObjects
        # memoizes ALL indexed-property calls — including zero-arg `x()` ones
        # (memoize-by-default flip, DO `4c71ccf`) — so a bare `versions()`
        # would serve its first read forever while the repo moves underneath
        # it, and a bare `write!` would replay a stale `:ok` instead of
        # executing (snag `hold-one-gitrepo-a9b4d2eb`). `@fresh` (DO
        # `312542d`, carried by the `DynamicObjects = "0.4.4, 0.5"` floor)
        # recomputes on every call. What stays memoized is pure: `read_version`
        # is addressed by immutable commit sha, `_ensure` is idempotent.

        # A missing file is seeded under the lock and re-checked there: an
        # unlocked seed could land after a concurrent `write!`/`update!` created
        # the file and replace that content with the default.
        @fresh current_content() = begin
            if !isfile(abs_path)
                Base.lock(_lock) do
                    isfile(abs_path) || _replace_file!(abs_path, default_content)
                end
            end
            read(abs_path, String)
        end

        @fresh current_version() = begin
            _ensure()
            repo = LibGit2.GitRepo(path)
            try
                _blob_sha_at(repo, "HEAD", relpath)
            finally
                close(repo)
            end
        end

        # Revisions OF THIS FILE, newest first: the commits where `relpath`
        # exists and its blob differs from EVERY parent's — git's own
        # `log -- <path>` simplification, so the result is independent of the
        # order the repo-wide walker happens to yield commits in.
        #
        # This used to compare each commit's blob against the PREVIOUS
        # ITERATION's and record the current (older) commit on a difference.
        # The walk is repo-WIDE and reverse-chronological, so that neighbour is
        # another file's commit as often as not: every entry came out one
        # recorded change too old, and HEAD was listed for every file whatever
        # it touched. The entry COUNT stayed right, which is what made it look
        # correct on a single-file repo (snag `editorroutes-the`).
        @fresh versions() = begin
            _ensure()
            Base.lock(_lock) do
                repo = LibGit2.GitRepo(path)
                try
                    out = NamedTuple{(:sha,:timestamp,:author,:message,:blob_sha),
                                     Tuple{String,Int64,String,String,String}}[]
                    walker = try
                        LibGit2.GitRevWalker(repo)
                    catch err
                        err isa LibGit2.GitError || rethrow()
                        return out
                    end
                    try
                        try
                            LibGit2.push_head!(walker)
                        catch err
                            err isa LibGit2.GitError || rethrow()
                            return out
                        end
                        for oid in walker
                            sha = string(oid)
                            blob = _blob_sha_at(repo, sha, relpath)
                            # Unborn or deleted here — no content to restore.
                            isempty(blob) && continue
                            any(p -> _blob_sha_at(repo, p, relpath) == blob,
                                _parent_shas(repo, sha)) && continue
                            commit = LibGit2.GitCommit(repo, oid)
                            try
                                sig = LibGit2.author(commit)
                                push!(out, (
                                    sha       = sha,
                                    timestamp = Int64(sig.time),
                                    author    = sig.name * " <" * sig.email * ">",
                                    message   = LibGit2.message(commit),
                                    blob_sha  = blob,
                                ))
                            finally
                                close(commit)
                            end
                        end
                    finally
                        close(walker)
                    end
                    out
                finally
                    close(repo)
                end
            end
        end

        read_version(sha) = __parent__.read_blob(sha * ":" * relpath)

        # Optimistic-concurrency write: `version` must match the current
        # blob_sha (or "" for a brand-new file). On mismatch returns
        # `(:conflict, current_blob_sha)` without writing.
        @fresh write!(content; version::AbstractString="",
                      message::AbstractString="edit " * relpath) = begin
            Base.lock(_lock) do
                _ensure()
                current = current_version()
                current == version || return (:conflict, current)
                _replace_file!(abs_path, content)
                repo = LibGit2.GitRepo(path)
                try
                    LibGit2.add!(repo, relpath)
                    sig = _signature()
                    oid = LibGit2.commit(repo, message; author=sig, committer=sig)
                    (:ok, string(oid))
                finally
                    close(repo)
                end
            end
        end

        # Atomic read-modify-write under the per-repo lock. `f(current_content)`
        # runs inside the lock; its return value is written and committed. For
        # partial-file edits (e.g. one key in a multi-key YAML) this avoids the
        # read-then-write race that `write!`'s optimistic concurrency would
        # report as a spurious conflict. Returns `(:ok, commit_sha)` on change
        # or `(:nochange, current_blob_sha)` if `f` returned identical content.
        @fresh update!(f; message::AbstractString="edit " * relpath) = begin
            Base.lock(_lock) do
                _ensure()
                current = isfile(abs_path) ? read(abs_path, String) : ""
                new_content = f(current)
                if new_content == current
                    return (:nochange, current_version())
                end
                _replace_file!(abs_path, new_content)
                repo = LibGit2.GitRepo(path)
                try
                    LibGit2.add!(repo, relpath)
                    sig = _signature()
                    oid = LibGit2.commit(repo, message; author=sig, committer=sig)
                    (:ok, string(oid))
                finally
                    close(repo)
                end
            end
        end
    end
end

include("routes/editor_routes.jl")

function __init__()
    # Per-process error log dir for caught route exceptions.
    ERROR_DIR[] = get(ENV, "HTMXO_ERROR_DIR", joinpath(tempdir(), "htmxo_errors"))
    _clear_operation_polls!()
    _RUNTIME_SESSION_SALT[] = rand(Random.RandomDevice(), UInt)
    isassigned(_managed_root_release_handler) ||
        (_managed_root_release_handler[] = nothing)
    # Record DynamicObjects' queued computations in the runtime ledger.
    _has_job_queue() && _dynamicobjects_queue(:observe_queue!)(_observe_queued!)
end

end # module HTMXObjects
